function normPersonName(s){return String(s||'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();}
function rosterDisplayName(e){return fullName(e||{});}
function attendanceDisplayName(e){return String((e&&e.name)||'').trim();}
function scheduleNameToPersonKey(s){let x=String(s||'').trim();if(!x||['none','open','pending','closed'].includes(x.toLowerCase()))return '';x=x.replace(/^(SUPV|LSO|SSO|SO|PSO|APS|ONIN|RECEP|Receptionist)\s+/i,'').trim();if(x.includes(',')){let parts=x.split(',');x=(parts[1]+' '+parts[0]).trim();}return normPersonName(x);}
function buildRosterIndexes(){const active=(roster.employees||[]).filter(e=>!e.archived&&e.status!=='Archived');const archived=(roster.employees||[]).filter(e=>e.archived||e.status==='Archived');const byName=new Map(),archByName=new Map(),byId=new Map();active.forEach(e=>{byName.set(normPersonName(rosterDisplayName(e)),e);byId.set(String(e.id),e);});archived.forEach(e=>archByName.set(normPersonName(rosterDisplayName(e)),e));return{active,archived,byName,archByName,byId};}
function buildAttendanceIndexes(){const active=(attendance.employees||[]).filter(e=>e.active!==false&&!e.archived&&e.status!=='Archived');const archived=(attendance.employees||[]).filter(e=>e.active===false||e.archived||e.status==='Archived');const byName=new Map(),byId=new Map();active.forEach(e=>{byName.set(normPersonName(attendanceDisplayName(e)),e);byId.set(String(e.id),e);});return{active,archived,byName,byId};}
function computeDataHealth(){const issues=[];const add=(severity,module,title,detail)=>issues.push({severity,module,title,detail});const ri=buildRosterIndexes(),ai=buildAttendanceIndexes();
 const rosterNameCounts={},attNameCounts={},eidCounts={};
 for(const e of roster.employees||[]){const nk=normPersonName(rosterDisplayName(e));if(nk)rosterNameCounts[nk]=(rosterNameCounts[nk]||0)+1;const eid=String(e.eid||'').trim().toUpperCase();if(eid&&eid!=='ONIN'&&eid!=='AUTOMATION')eidCounts[eid]=(eidCounts[eid]||0)+1;if(!e.last&&!e.first)add('warning','Roster','Blank roster name','Roster employee id '+(e.id||'?')+' is missing first/last name.');if(!e.shift)add('warning','Roster','Missing shift',rosterDisplayName(e)+' does not have a shift.');if(!Array.isArray(e.rdo))add('warning','Roster','Invalid RDO',rosterDisplayName(e)+' has missing or invalid RDO values.');}
 for(const e of attendance.employees||[]){const nk=normPersonName(attendanceDisplayName(e));if(nk)attNameCounts[nk]=(attNameCounts[nk]||0)+1;if(!attendanceDisplayName(e))add('warning','Attendance','Blank attendance name','Attendance employee id '+(e.id||'?')+' is missing a name.');if(!e.shift)add('warning','Attendance','Missing shift',attendanceDisplayName(e)+' does not have a shift.');}
 Object.keys(rosterNameCounts).filter(k=>rosterNameCounts[k]>1).forEach(k=>add('warning','Roster','Duplicate roster name',k+' appears '+rosterNameCounts[k]+' times.'));
 Object.keys(attNameCounts).filter(k=>attNameCounts[k]>1).forEach(k=>add('warning','Attendance','Duplicate attendance name',k+' appears '+attNameCounts[k]+' times.'));
 Object.keys(eidCounts).filter(k=>eidCounts[k]>1).forEach(k=>add('critical','Roster','Duplicate EID',k+' appears '+eidCounts[k]+' times in active/archived roster data.'));
 for(const e of ri.active){const key=normPersonName(rosterDisplayName(e));if(key&&!ai.byName.has(key))add('info','Roster/Attendance','Roster employee not linked to Attendance',rosterDisplayName(e)+' is active in Roster but not matched in Attendance.');}
 for(const e of ai.active){const key=normPersonName(attendanceDisplayName(e));if(key&&!ri.byName.has(key))add('warning','Roster/Attendance','Attendance employee missing from active Roster',attendanceDisplayName(e)+' is active in Attendance but not matched in active Roster.');}
 for(const e of ai.active){const key=normPersonName(attendanceDisplayName(e));if(key&&ri.archByName.has(key))add('critical','Roster/Attendance','Archived employee still active in Attendance',attendanceDisplayName(e)+' is archived in Roster but still active in Attendance.');}
 const validRosterKeys=new Set([...ri.byName.keys(),...ri.archByName.keys()]);for(const row of roster.schedule||[]){for(const d of row.days||[]){const k=scheduleNameToPersonKey(d);if(k&&!validRosterKeys.has(k))add('warning','Schedule','Schedule assignment not found in Roster',String(d)+' in '+(row.section||'Schedule')+' / '+(row.post||'post')+' does not match a roster employee.');if(k&&ri.archByName.has(k))add('critical','Schedule','Archived person on schedule',String(d)+' appears on the schedule but is archived.');}}
 const topicById=new Map((roster.trainingTopics||[]).map(t=>[String(t.id),t]));for(const tr of roster.trainingRecords||[]){if(!ri.byId.has(String(tr.employeeId)))add('warning','Training','Training record for missing employee','Training record '+(tr.id||'?')+' points to employeeId '+(tr.employeeId||'?')+'.');const topic=topicById.get(String(tr.topicId));if(topic&&Number(topic.interval||topic.renewalDays||0)>0&&!tr.dueDate)add('warning','Training','Missing due date','Training record '+(tr.id||'?')+' is tied to renewable topic '+(topic.name||topic.title||tr.topicId)+' but has no due date.');if(tr.dueDate&&tr.dueDate<new Date().toISOString().slice(0,10))add('info','Training','Overdue training record','Training record '+(tr.id||'?')+' due '+tr.dueDate+'.');}
 for(const e of roster.employees||[]){const nm=rosterDisplayName(e);[['shirt','shirtStatus'],['pants','pantsStatus'],['jacket','jacketStatus']].forEach(pair=>{const size=e[pair[0]],status=String(e[pair[1]]||'').toLowerCase();if(['needed','ordered','issued'].includes(status)&&!size)add('warning','Uniforms','Uniform status without size',nm+' has '+pair[0]+' marked '+status+' but no size entered.');});}
 const today=new Date().toISOString().slice(0,10);for(const t of tasks.tasks||[]){if(t.status!=='Complete'&&t.status!=='Archived'){if(t.dueDate&&t.dueDate<today)add('warning','Tasks','Overdue active task',t.project+' was due '+t.dueDate+'.');if(!t.status)add('warning','Tasks','Task missing status',t.project+' has no status.');if(!t.update)add('info','Tasks','Task missing update',t.project+' has no current update.');if(t.status!=='Complete'&&!t.nextStep)add('info','Tasks','Task missing next step',t.project+' has no next step.');}}
 const critical=issues.filter(i=>i.severity==='critical').length,warning=issues.filter(i=>i.severity==='warning').length,info=issues.filter(i=>i.severity==='info').length;return{issues,critical,warning,info,ok:critical===0&&warning===0};}
function renderDataHealth(){const h=computeDataHealth();const modules=['all',...Array.from(new Set(h.issues.map(i=>i.module)))];return `<div class="page-head"><div><div class="page-title">Data Health Check</div><div class="page-sub">Read-only integrity checks across Attendance, Roster, Schedule, Training, Uniforms, and Tasks.</div></div><div class="btn-group"><button class="primary" onclick="safeRenderPages()">Run Check Again</button><button onclick="printDataHealth()">Print</button></div></div><div class="health-summary"><div class="health-pill"><strong>${h.issues.length}</strong><span>Total Issues</span></div><div class="health-pill"><strong>${h.critical}</strong><span>Critical</span></div><div class="health-pill"><strong>${h.warning}</strong><span>Warnings</span></div><div class="health-pill"><strong>${h.info}</strong><span>Info</span></div></div>${h.issues.length===0?'<div class="card"><div class="card-title">Result</div><p>No data health issues found.</p></div>':`<div class="card"><div class="card-title">Findings</div><div class="issue-list">${h.issues.map(i=>`<div class="issue-card ${esc(i.severity)}"><div class="issue-top"><div class="issue-title">${esc(i.title)}</div><div class="issue-meta">${esc(i.severity)} · ${esc(i.module)}</div></div><div class="issue-detail">${esc(i.detail)}</div></div>`).join('')}</div></div>`}`;}
function printDataHealth(){const h=computeDataHealth();const html=`<html><head><title>PWADC Data Health Check</title><style>body{font-family:Arial,sans-serif;padding:24px}h1{margin-bottom:4px}.issue{border:1px solid #ccc;border-left:5px solid #999;margin:8px 0;padding:8px}.critical{border-left-color:#c0272d}.warning{border-left-color:#e08a2f}.info{border-left-color:#4a90d9}.meta{font-size:12px;color:#555;text-transform:uppercase}</style></head><body><h1>PWADC Data Health Check</h1><p>${new Date().toLocaleString()} · ${h.issues.length} issue(s)</p>${h.issues.map(i=>`<div class="issue ${esc(i.severity)}"><strong>${esc(i.title)}</strong><div class="meta">${esc(i.severity)} · ${esc(i.module)}</div><div>${esc(i.detail)}</div></div>`).join('')||'<p>No issues found.</p>'}</body></html>`;const w=window.open('','_blank');w.document.write(html);w.document.close();w.print();}
async function loadRestoreBackups(module){restoreSelectedModule=module||restoreSelectedModule;restoreLoading=true;safeRenderPages();try{const r=await SuiteBridge.send('suite:listBackups',{}, {module:restoreSelectedModule});restoreBackups=r.backups||[];}catch(e){toast('Backup list failed: '+e.message);restoreBackups=[];}restoreLoading=false;safeRenderPages();}
async function restoreBackup(module,path){if(!confirm('Restore '+module+' from this backup? Current live data will be backed up first.'))return;try{const r=await SuiteBridge.send('suite:restoreBackup',{module,path});if(module==='attendance'){attendance=JSON.parse(r.data||'{}');normalizeAttendance();}else if(module==='roster'){roster=JSON.parse(r.data||'{}');normalizeRoster();}else if(module==='tasks'){tasks=JSON.parse(r.data||'{}');normalizeTasks();}else if(module==='suite-settings'){settings=normalizeSettings(JSON.parse(r.data||'{}'));applyTheme();}toast('Restored '+module+' backup');safeRenderPages();}catch(e){toast('Restore failed: '+e.message);}}
async function restoreEverythingLatest(){if(!confirm('Restore the latest backup for Attendance, Roster, Tasks, and Settings? Current files will be backed up first.'))return;for(const m of ['attendance','roster','tasks','suite-settings']){try{const r=await SuiteBridge.send('suite:listBackups',{}, {module:m});const b=(r.backups||[])[0];if(b)await restoreBackup(m,b.path);}catch(e){toast('Restore '+m+' failed: '+e.message)}}}
function renderRestoreCenter(){const mods=[['attendance','Attendance'],['roster','Roster'],['tasks','Task Tracker'],['suite-settings','Suite Settings'],['programs','Standalone Programs']];return `<div class="page-head"><div><div class="page-title">Restore Center</div><div class="page-sub">Controlled recovery from JSON backups. The current live file is backed up before any restore.</div></div><div class="btn-group"><button class="primary" onclick="backupEverything()">Backup Everything First</button><button onclick="SuiteBridge.send('suite:openPath',{path:settings.dataRoot+'\\\\Backups'}).catch(e=>toast('Open backup folder failed: '+e.message))">Open Backup Folder</button></div></div><div class="restore-grid"><div class="card"><div class="card-title">Backup Sets</div><div class="restore-module-list">${mods.map(m=>`<button class="${restoreSelectedModule===m[0]?'active':''}" onclick="loadRestoreBackups('${m[0]}')">${m[1]}</button>`).join('')}</div><div class="small-note" style="margin-top:12px">Use this screen when a build or sync operation damages live data. Restores are deliberate, backed up, and module-specific.</div></div><div class="card"><div class="card-title">${esc(mods.find(m=>m[0]===restoreSelectedModule)?.[1]||restoreSelectedModule)} Backups</div>${restoreLoading?'<p>Loading backups...</p>':restoreBackups.length===0?`<p class="small-note">No backups loaded. Click a module on the left, or there are no backups for this module yet.</p>`:`${restoreBackups.map(b=>`<div class="backup-row"><div><div class="backup-name">${esc(b.name)}</div><div class="backup-meta">${esc(b.path)}</div></div><div class="backup-meta">${esc(b.modified||'')}</div><div><button class="danger" onclick="restoreBackup('${restoreSelectedModule}','${escAttr(b.path)}')">Restore This</button></div></div>`).join('')}`}</div></div>`;}
function combinedChangeLog(){const rows=[];for(const a of attendance.audit||[])rows.push({...a,module:'Attendance'});for(const a of roster.audit||[])rows.push({...a,module:'Roster'});for(const a of tasks.audit||[])rows.push({...a,module:'Task Tracker'});rows.sort((a,b)=>String(b.at||'').localeCompare(String(a.at||'')));return rows;}
function renderChangeLog(){let rows=combinedChangeLog();if(changeLogModule!=='all')rows=rows.filter(r=>r.module===changeLogModule);if(changeLogSearch)rows=rows.filter(r=>(String(r.action||'')+' '+String(r.detail||'')+' '+String(r.user||'')+' '+String(r.machine||'')).toLowerCase().includes(changeLogSearch.toLowerCase()));const mods=['all','Attendance','Roster','Task Tracker'];return `<div class="page-head"><div><div class="page-title">Change Log</div><div class="page-sub">Combined audit trail from Attendance, Roster, and Task Tracker.</div></div><button onclick="printChangeLog()">Print</button></div><div class="card"><div class="log-filter"><select onchange="changeLogModule=this.value;safeRenderPages()">${mods.map(m=>`<option value="${m}" ${changeLogModule===m?'selected':''}>${m==='all'?'All Modules':m}</option>`).join('')}</select><input placeholder="Search changes..." value="${esc(changeLogSearch)}" oninput="changeLogSearch=this.value;safeRenderPages()"></div><div>${rows.slice(0,500).map(r=>`<div class="log-row"><div>${esc(r.at?new Date(r.at).toLocaleString():'')}</div><div>${esc(r.module||'')}</div><div class="log-action">${esc(r.action||'')}</div><div class="log-detail"><strong>${esc(r.user||'')}</strong> ${r.machine?`@ ${esc(r.machine)}`:''}<br>${esc(r.detail||'')}</div></div>`).join('')||'<p class="small-note">No matching audit entries.</p>'}</div></div>`;}
function printChangeLog(){const rows=combinedChangeLog().slice(0,500);const html=`<html><head><title>PWADC Change Log</title><style>body{font-family:Arial,sans-serif;padding:24px}.row{border-bottom:1px solid #ccc;padding:6px 0}.meta{font-size:12px;color:#555}</style></head><body><h1>PWADC Change Log</h1><p>${new Date().toLocaleString()}</p>${rows.map(r=>`<div class="row"><strong>${esc(r.module)} · ${esc(r.action||'')}</strong><div class="meta">${esc(r.at?new Date(r.at).toLocaleString():'')} · ${esc(r.user||'')} ${r.machine?'@ '+esc(r.machine):''}</div><div>${esc(r.detail||'')}</div></div>`).join('')}</body></html>`;const w=window.open('','_blank');w.document.write(html);w.document.close();w.print();}
function escAttr(s){return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');}

function renderHome(){const flags=computeFlags();const health=computeDataHealth();const openTasks=(tasks.tasks||[]).filter(t=>t.status!=='Complete'&&t.status!=='Archived'&&t.status!=='On Hold').length;return `<div class="page-head"><div><div class="page-title">Security Operations Dashboard</div><div class="page-sub">${env.user||'User'} @ ${env.machine||'Machine'} · v2.7.1</div></div><div class="btn-group"><button onclick="navigate('data-health')">Run Data Health</button><button class="gold" onclick="backupEverything()">Backup Everything</button></div></div><div class="grid cols-3"><div class="kpi"><div class="num">${activeAttendanceEmployees().length}</div><div class="lbl">Active Attendance Employees</div></div><div class="kpi"><div class="num">${roster.employees.length}</div><div class="lbl">Roster Employees</div></div><div class="kpi"><div class="num">${flags.filter(f=>!f.addressed).length}</div><div class="lbl">Open Attendance Exceptions</div></div><div class="kpi"><div class="num">${openTasks}</div><div class="lbl">Active Tasks</div></div><div class="kpi"><div class="num">${health.critical}/${health.warning}</div><div class="lbl">Critical / Warning Health Issues</div></div><div class="kpi"><div class="num">${attendance.lastSaved?new Date(attendance.lastSaved).toLocaleDateString():'-'}</div><div class="lbl">Attendance Last Saved</div></div></div><div class="grid cols-2">${['attendance','roster','tasks','data-health','restore','change-log','other-programs'].map(id=>`<div class="card module-card" onclick="navigate('${id}')"><h3>${MODULES.find(m=>m.id===id).label}</h3><p>${id==='attendance'?'Daily entry, 90-day grid, exceptions, clear by person/code, and shared JSON storage.':id==='roster'?'Staff records, master schedule, uniforms, training, print/export, and shared JSON storage.':id==='tasks'?'Project/task tracker, weekly boss update email/export, status, priority, owner, and follow-up tracking.':id==='data-health'?'Read-only integrity checks for duplicate employees, broken roster/attendance links, schedule problems, training gaps, uniforms, and task issues.':id==='restore'?'Controlled restore from backups. Creates a fresh backup before restoring live data.':id==='change-log'?'Combined audit trail from Attendance, Roster, and Task Tracker so changes are visible.':'Launch standalone specialist tools: Badge Audit, AMAG Audit, and Access Audit. Keeps the suite stable while preserving each tool’s original workflow.'}</p></div>`).join('')}</div>`}

function renderOtherPrograms(){return `<div class="page-head"><div><div class="page-title">Other Programs</div><div class="page-sub">Standalone specialist tools launched outside the main suite to avoid script collisions and preserve the original workflows.</div></div><div class="btn-group"><button onclick="refreshStandalonePrograms()">Refresh Program Files</button><button onclick="SuiteBridge.send('suite:openPath',{path:programBasePath()}).catch(e=>toast('Open Programs folder failed: '+e.message))">Open Programs Folder</button></div></div><div class="notice">Program files are stored under <strong>${esc(programBasePath())}</strong>. The suite copies the packaged versions there on startup. If a tool is updated, use Refresh Program Files.</div><div class="grid cols-3">${OTHER_PROGRAMS.map(p=>`<div class="card module-card"><h3>${esc(p.title)}</h3><p>${esc(p.purpose)}</p><div class="notice" style="margin-top:12px"><strong>Expected file:</strong><br>${esc('Programs\\'+p.folder+'\\'+p.file)}</div><div class="btn-group" style="margin-top:14px"><button class="primary" onclick="openProgram('${p.id}')">Open Program</button><button onclick="openProgramFolder('${p.id}')">Open Folder</button></div></div>`).join('')}</div>`}

function renderRoster(){return `<div class="page-head roster-page-head"><div><div class="page-title">Roster</div><div class="page-sub">Staff records, schedule, training, uniforms, and labor analytics. This module uses the shared roster JSON and keeps the original Staff Manager workflow as the blueprint.</div></div><div class="roster-utility-actions"><button onclick="document.getElementById('rosterImportFile').click()">Import JSON</button><button onclick="reloadPackagedRosterData()">Use Packaged Latest JSON</button><button onclick="createRosterBackup()">Backup Now</button><button onclick="syncAttendanceFromRoster(true)">Link Existing Attendance</button><button onclick="hideAttendanceSyncDuplicates()">Hide Sync Duplicates</button><button onclick="showArchivedRoster=!showArchivedRoster;safeRenderPages()">Archive / Old Employees</button><button onclick="exportRosterCSV()">Export CSV</button><input id="rosterImportFile" type="file" accept=".json,application/json" class="hidden" onchange="importRosterJSON(this)"></div></div><div class="subnav">${['roster','schedule','training','uniforms','analytics'].map(v=>`<button class="${activeRosterView===v?'active':''}" onclick="activeRosterView='${v}';safeRenderPages()">${v==='roster'?'Roster':v==='schedule'?'Schedule':v==='training'?'Training':v==='uniforms'?'Uniforms':'Analytics'}</button>`).join('')}</div>${activeRosterView==='roster'?renderRosterList():activeRosterView==='schedule'?renderRosterSchedule():activeRosterView==='training'?renderRosterTraining():activeRosterView==='uniforms'?renderRosterUniforms():renderRosterAnalytics()}`}
function renderRosterList(){const list=filteredRoster();const activeEmps=rosterActiveEmployees();const archiveCount=rosterArchivedEmployees().length;const total=activeEmps.length;const hourly=activeEmps.filter(e=>(e.type||'')==='Hourly').length;const salary=activeEmps.filter(e=>(e.type||'')==='Salary').length;const openUni=activeEmps.reduce((n,e)=>n+['shirt','pants','jacket'].filter(k=>(e[k+'Status']||'')&&e[k+'Status']!=='issued').length,0);return `<div class="grid cols-4 roster-summary"><div class="kpi"><div class="num">${total}</div><div class="lbl">Employees</div></div><div class="kpi"><div class="num">${hourly}</div><div class="lbl">Hourly</div></div><div class="kpi"><div class="num">${salary}</div><div class="lbl">Salary</div></div><div class="kpi"><div class="num">${openUni}</div><div class="lbl">Uniform Needs / Orders</div></div></div><div class="card roster-workbar-card"><div class="card-title">Roster Controls</div><div class="roster-filters roster-workbar"><div><label>Search</label><input value="${esc(rosterSearch)}" placeholder="Name, EID, rank, shift..." oninput="rosterSearch=this.value;safeRenderPages()"></div><div><label>Shift</label><select onchange="rosterShiftFilter=this.value;safeRenderPages()"><option value="all">All Shifts</option>${rosterShifts().map(x=>`<option value="${esc(x)}" ${rosterShiftFilter===x?'selected':''}>${esc(x)}</option>`).join('')}</select></div><div><label>Rank</label><select onchange="rosterRankFilter=this.value;safeRenderPages()"><option value="all">All Ranks</option>${rosterRanks().map(x=>`<option value="${esc(x)}" ${rosterRankFilter===x?'selected':''}>${esc(rankLong(x))}</option>`).join('')}</select></div><div><label>Type</label><select onchange="rosterTypeFilter=this.value;safeRenderPages()"><option value="all">All Types</option>${rosterTypes().map(x=>`<option value="${esc(x)}" ${rosterTypeFilter===x?'selected':''}>${esc(x)}</option>`).join('')}</select></div><div class="top-actions"><button class="primary" onclick="openEmployeeModal()">+ Add Employee</button><button onclick="openRosterPrintModal()">Print Roster</button><button onclick="exportRosterCSV()">Export CSV</button></div></div><div class="mini-note">Showing ${list.length} of ${total} active employees. ${archiveCount} archived / old employee(s) hidden by default. Showing live roster records from shared JSON. Employee management, promote, merit, remove, import/export, and custom print are active. Schedule, uniforms, analytics, and training continue in staged rebuilds.</div></div><div class="table-wrap"><table class="wide-table roster-table"><thead><tr><th>Name</th><th>EID</th><th>Rank</th><th>Shift</th><th>Gate Shift</th><th>Rate</th><th>Type</th><th>RDO</th><th>Uniform</th><th>DOH</th><th>DOP</th><th>Notes</th><th>Actions</th></tr></thead><tbody>${list.map(e=>`<tr><td><strong>${esc(fullName(e))}</strong></td><td>${esc(e.eid||'')}</td><td>${rankBadge(e.rank)}</td><td>${esc(e.shift||'')}</td><td>${esc(e.gateShift||'')}</td><td>${money(e.rate)}</td><td>${esc(e.type||'')}</td><td>${esc((e.rdo||[]).join('/'))}</td><td>${uniformSummary(e)}</td><td>${esc(fmtDate(e.doh))}</td><td>${esc(fmtDate(e.dop))}</td><td class="notes-cell">${esc(e.notes||'')}</td><td><div class="td-actions"><button class="sm" onclick="openEmployeeModal('${esc(e.id)}')">Edit</button><button class="sm gold" onclick="openPromoteModal('${esc(e.id)}')">Promote</button><button class="sm" onclick="openMeritModal('${esc(e.id)}')">Merit</button><button class="sm danger" onclick="removeRosterEmployee('${esc(e.id)}')">Remove</button></div></td></tr>`).join('')||'<tr><td colspan="13">No roster records match the current filters.</td></tr>'}</tbody></table></div>${renderArchivedRosterSection()}`}
function rosterTypes(){return [...new Set(roster.employees.map(e=>e.type||'').filter(Boolean))].sort()}
function rankLong(rank){return ({PSO:'Security Trainee',SO:'Security Officer',SSO:'Senior Security Officer',LSO:'Lead Security Officer',SUPV:'Supervisor',ONIN:'ONIN',APS:'APS',Receptionist:'Receptionist'}[rank]||rank||'')}
function rankBadge(rank){let cls=String(rank||'').toLowerCase().replace(/[^a-z0-9]/g,'');return `<span class="rank-badge ${cls}">${esc(rank||'')}</span>`}
function money(v){let n=Number(v);return Number.isFinite(n)&&n>0?'$'+n.toFixed(2):''}
function fmtDate(d){if(!d)return '';let x=new Date(d+'T00:00:00');return isNaN(x)?d:x.toLocaleDateString()}
function uniformSummary(e){let chips=[];for(const k of ['shirt','pants','jacket']){let st=e[k+'Status']||'';let size=e[k]||'';if(st)chips.push(`<span class="uniform-chip ${esc(st)}">${k[0].toUpperCase()} ${esc(size)} ${esc(st)}</span>`)}return `<div class="uniform-needs">${chips.join('')||'<span class="mini-note">Not set</span>'}</div>`}
function filteredRoster(){let q=(rosterSearch||'').toLowerCase();return rosterActiveEmployees().filter(e=>{let blob=[fullName(e),e.eid,e.rank,e.shift,e.gateShift,e.type,e.notes].join(' ').toLowerCase();return (!q||blob.includes(q))&&(rosterShiftFilter==='all'||e.shift===rosterShiftFilter)&&(rosterRankFilter==='all'||e.rank===rosterRankFilter)&&(rosterTypeFilter==='all'||e.type===rosterTypeFilter)}).sort((a,b)=>rosterShift(a).localeCompare(rosterShift(b))||fullName(a).localeCompare(fullName(b)))}
function renderArchivedRosterSection(){const list=rosterArchivedEmployees();if(!list.length)return '';return `<div class="archive-panel"><div class="archive-head" onclick="showArchivedRoster=!showArchivedRoster;safeRenderPages()"><div><div class="archive-title">Archive / Old Employees</div><div class="page-sub">Hidden by default. These records stay out of daily roster views but remain available for reference.</div></div><button onclick="showArchivedRoster=!showArchivedRoster;event.stopPropagation()">${showArchivedRoster?'Hide':'Show'} Archive (${list.length})</button></div>${showArchivedRoster?`<div class="archive-body"><div class="table-wrap"><table class="wide-table roster-table"><thead><tr><th>Name</th><th>EID</th><th>Rank</th><th>Shift</th><th>Archived</th><th>Notes</th><th>Actions</th></tr></thead><tbody>${list.map(e=>`<tr class="archived-row"><td><strong>${esc(fullName(e))}</strong> <span class="archive-badge">Archived</span></td><td>${esc(e.eid||'')}</td><td>${rankBadge(e.rank)}</td><td>${esc(e.shift||'')}</td><td>${esc(e.archivedAt?new Date(e.archivedAt).toLocaleDateString():'')}</td><td>${esc(e.notes||'')}</td><td><div class="td-actions"><button class="sm" onclick="openEmployeeModal('${esc(e.id)}')">Edit</button><button class="sm gold" onclick="restoreArchivedEmployee('${esc(e.id)}')">Restore</button><button class="sm danger" onclick="deleteArchivedEmployee('${esc(e.id)}')">Delete</button></div></td></tr>`).join('')}</tbody></table></div></div>`:''}</div>`}
async function restoreArchivedEmployee(id){let e=roster.employees.find(x=>String(x.id)===String(id));if(!e)return;e.archived=false;e.status='Active';delete e.archivedAt;roster.audit.push({at:new Date().toISOString(),user:env.user||'',action:'Employee restored',detail:fullName(e)});const ok=await saveRosterNow('employee-restore');if(ok){await syncAttendanceFromRoster(false);safeRenderPages();toast('Employee restored and synced to Attendance')}} 
async function deleteArchivedEmployee(id){
  let idx=(roster.employees||[]).findIndex(x=>String(x.id)===String(id));
  if(idx<0)return;
  let e=roster.employees[idx];
  if(!isArchivedEmployee(e)){toast('Only archived employees can be deleted from this section.');return;}
  if(!confirm('Permanently delete '+fullName(e)+' from the Roster archive? Attendance history will not be deleted.'))return;
  roster.employees.splice(idx,1);
  roster.audit=roster.audit||[];
  roster.audit.push({at:new Date().toISOString(),user:env.user||'',action:'Archived employee deleted from roster archive',detail:fullName(e)});
  let attChanged=false;
  for(let i=(attendance.employees||[]).length-1;i>=0;i--){
    const ae=attendance.employees[i];
    if(ae&&String(ae.rosterId||'')===String(id)){
      const hist=attendance.attendance&&attendance.attendance[ae.id]?Object.keys(attendance.attendance[ae.id]).length:0;
      if(hist===0){
        attendance.employees.splice(i,1);
        if(attendance.attendance)delete attendance.attendance[ae.id];
        attChanged=true;
      }else{
        ae.active=false;ae.archived=true;ae.status='Deleted from Roster Archive';ae.archivedAt=ae.archivedAt||new Date().toISOString();
        attChanged=true;
      }
    }
  }
  const ok=await saveRosterNow('archive-delete');
  if(attChanged)await saveAttendance('archive-delete-sync');
  if(ok){safeRenderPages();toast('Archived employee deleted from roster archive. Attendance history preserved.')}
}

function openEmployeeModal(id=''){let e=id?roster.employees.find(x=>String(x.id)===String(id)):null;e=e||{last:'',first:'',eid:'',doh:'',dop:'',rank:'PSO',shift:'1st',gateShift:'',rate:17,type:'Hourly',shirt:'',pants:'',jacket:'',shirtStatus:'',pantsStatus:'',jacketStatus:'',notes:'',rdo:[]};let days=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];showModal(`<div class="modal-head"><div class="modal-title">${id?'Edit Employee':'Add Employee'}</div><button onclick="closeModal()">Close</button></div><div class="form-grid"><div><label>Last Name</label><input id="empLast" value="${esc(e.last||'')}"></div><div><label>First Name</label><input id="empFirst" value="${esc(e.first||'')}"></div><div><label>EID</label><input id="empEid" value="${esc(e.eid||'')}"></div><div><label>Date of Hire</label><input id="empDoh" type="date" value="${esc(e.doh||'')}"></div><div><label>Date of Promotion</label><input id="empDop" type="date" value="${esc(e.dop||'')}"></div><div><label>Current Rank</label><select id="empRank">${['PSO','SO','SSO','LSO','SUPV','Receptionist','ONIN','APS'].map(r=>`<option value="${r}" ${e.rank===r?'selected':''}>${rankLong(r)}</option>`).join('')}</select></div><div><label>Shift</label><select id="empShift" onchange="updateGateShiftControls()">${['1st','2nd','3rd','GATE','DOCK','RECP','Crosswalk','W/E Gate'].map(x=>`<option ${e.shift===x?'selected':''}>${x}</option>`).join('')}</select></div><div id="gateShiftGroup"><label>Gate Shift Assignment</label><select id="empGateShift">${['','0400-1200','1200-2000','2000-0400','0400-1600','1600-0400'].map(x=>`<option value="${x}" ${(e.gateShift||'')===x?'selected':''}>${x?((x==='0400-1600'||x==='1600-0400')?'W/E only: ':'Gate: ')+x:'None'}</option>`).join('')}</select></div><div><label>Pay Rate</label><input id="empRate" type="number" step="0.01" min="0" value="${esc(e.rate??'')}"></div><div><label>Employment Type</label><select id="empType">${['Hourly','Salary','Onin','APS'].map(t=>`<option ${e.type===t?'selected':''}>${t}</option>`).join('')}</select></div><div><label>Shirt Size</label><select id="empShirt">${['','XS','S','M','L','XL','2X','3X','4X','5X'].map(x=>`<option value="${x}" ${(e.shirt||'')===x?'selected':''}>${x}</option>`).join('')}</select></div><div><label>Shirt Status</label><select id="empShirtStatus">${['','needed','ordered','issued'].map(t=>`<option value="${t}" ${(e.shirtStatus||'')===t?'selected':''}>${t||'Not Set'}</option>`).join('')}</select></div><div><label>Pants Size</label><input id="empPants" value="${esc(e.pants||'')}" placeholder="32/34 or 14"></div><div><label>Pants Status</label><select id="empPantsStatus">${['','needed','ordered','issued'].map(t=>`<option value="${t}" ${(e.pantsStatus||'')===t?'selected':''}>${t||'Not Set'}</option>`).join('')}</select></div><div><label>Jacket Size</label><select id="empJacket">${['','XS','S','M','L','XL','2X','3X','4X','5X'].map(x=>`<option value="${x}" ${(e.jacket||'')===x?'selected':''}>${x}</option>`).join('')}</select></div><div><label>Jacket Status</label><select id="empJacketStatus">${['','needed','ordered','issued'].map(t=>`<option value="${t}" ${(e.jacketStatus||'')===t?'selected':''}>${t||'Not Set'}</option>`).join('')}</select></div><div class="full"><label>Regular Days Off</label><div class="day-grid">${days.map(d=>`<label class="day-check"><input type="checkbox" class="rdoBox" value="${d}" ${(e.rdo||[]).includes(d)?'checked':''}> ${d}</label>`).join('')}</div></div><div class="full"><label>Notes</label><textarea id="empNotes">${esc(e.notes||'')}</textarea></div></div><div class="modal-actions"><button onclick="closeModal()">Cancel</button><button class="primary" onclick="saveEmployeeModal('${esc(id)}')">Save Employee</button></div>`);setTimeout(updateGateShiftControls,0)}
function updateGateShiftControls(){let sh=document.getElementById('empShift'),g=document.getElementById('gateShiftGroup');if(!sh||!g)return;g.style.display=(sh.value==='GATE'||sh.value==='W/E Gate')?'block':'none'}
async function saveEmployeeModal(id=''){
  try{
    const btn=document.querySelector('#modalBackdrop .modal-actions .primary, #modalBackdrop .form-actions .primary');
    if(btn){btn.disabled=true;btn.textContent='Saving...';}
    roster.employees=Array.isArray(roster.employees)?roster.employees:[];
    roster.audit=Array.isArray(roster.audit)?roster.audit:[];
    roster.nextId=Number(roster.nextId||0)||((roster.employees.reduce((m,e)=>Math.max(m,Number(e.id)||0),0))+1);
    let existing=id?roster.employees.find(e=>String(e.id)===String(id)):null;
    const wasNewEmployee=!existing;
    let e=existing||{id:roster.nextId++};
    const last=val('empLast').trim(), first=val('empFirst').trim();
    if(!last&&!first){toast('Employee needs a first or last name');if(btn){btn.disabled=false;btn.textContent='Save Employee';}return;}
    Object.assign(e,{last,first,eid:val('empEid').trim(),rank:val('empRank'),shift:val('empShift'),gateShift:val('empGateShift'),rate:Number(val('empRate')||0),type:val('empType'),doh:val('empDoh'),dop:val('empDop'),shirt:val('empShirt'),pants:val('empPants'),jacket:val('empJacket'),shirtStatus:val('empShirtStatus'),pantsStatus:val('empPantsStatus'),jacketStatus:val('empJacketStatus'),notes:val('empNotes'),rdo:[...document.querySelectorAll('.rdoBox:checked')].map(x=>x.value)});
    if(!existing)roster.employees.push(e);
    roster.audit.push({at:new Date().toISOString(),user:env.user||'',action:id?'Employee updated':'Employee added',detail:fullName(e)});
    const ok=await saveRosterNow(id?'employee-update':'employee-add');
    if(!ok){if(btn){btn.disabled=false;btn.textContent='Save Employee';}return;}
    try{await syncOneRosterEmployeeToAttendance(e,wasNewEmployee); await saveAttendanceNow(wasNewEmployee?'roster-add-employee-sync':'roster-edit-employee-sync');}catch(syncErr){reportActionError('Roster to Attendance sync',syncErr);}
    closeModal();safeRenderPages();toast(wasNewEmployee?'Roster employee added and synced to Attendance':'Roster employee saved and synced to Attendance');
  }catch(e){reportActionError('Save employee',e);}
}
async function removeRosterEmployee(id){let e=roster.employees.find(x=>String(x.id)===String(id));if(!e)return;if(!confirm('Archive '+fullName(e)+' as an old employee? Attendance history will stay preserved.'))return;e.archived=true;e.status='Archived';e.archivedAt=e.archivedAt||new Date().toISOString();roster.audit.push({at:new Date().toISOString(),user:env.user||'',action:'Employee archived',detail:fullName(e)});const ok=await saveRosterNow('employee-archive');if(ok){await syncAttendanceFromRoster(false);safeRenderPages();toast('Employee moved to Archive / Old Employees')}}
function openPromoteModal(id){let e=roster.employees.find(x=>String(x.id)===String(id));if(!e)return;let ranks=['PSO','SO','SSO','LSO','SUPV','Receptionist','ONIN','APS'];let idx=Math.max(0,ranks.indexOf(e.rank));let suggested=ranks[Math.min(idx+1,ranks.length-1)]||e.rank;showModal(`<div class="modal-head"><div class="modal-title">Promote Employee</div><button onclick="closeModal()">Close</button></div><div class="notice"><strong>${esc(fullName(e))}</strong><br>Current rank: ${esc(e.rank||'')}</div><div class="form-grid"><div><label>New Rank</label><select id="promoRank">${ranks.map(r=>`<option value="${r}" ${r===suggested?'selected':''}>${rankLong(r)}</option>`).join('')}</select></div><div><label>Effective Date</label><input id="promoDate" type="date" value="${new Date().toISOString().slice(0,10)}"></div><div><label>New Rate</label><input id="promoRate" type="number" step="0.01" value="${esc(e.rate??'')}"></div><div><label>Update Schedule Labels</label><select id="promoSchedule"><option value="yes">Yes</option><option value="no">No</option></select></div><div class="full"><label>Note</label><textarea id="promoNote">Promoted from ${esc(e.rank||'')} to ${esc(suggested)}.</textarea></div></div><div class="modal-actions"><button onclick="closeModal()">Cancel</button><button class="gold" onclick="confirmPromote('${esc(id)}')">Confirm Promotion</button></div>`)}
function confirmPromote(id){let e=roster.employees.find(x=>String(x.id)===String(id));if(!e)return;let oldRank=e.rank,newRank=val('promoRank');let oldLabel=(oldRank?oldRank+' ':'')+fullName(e),newLabel=(newRank?newRank+' ':'')+fullName(e);e.rank=newRank;e.dop=val('promoDate')||e.dop;e.rate=Number(val('promoRate')||e.rate||0);if(val('promoSchedule')==='yes'){for(const r of roster.schedule||[]){r.days=(r.days||[]).map(d=>d===oldLabel?newLabel:d)}}roster.audit.push({at:new Date().toISOString(),user:env.user||'',action:'Employee promoted',detail:fullName(e)+' '+oldRank+' -> '+newRank});saveRosterNow('promotion').then(async ok=>{if(ok){await syncAttendanceFromRoster(false);closeModal();safeRenderPages();toast('Promotion applied and synced to Attendance')}})}
function openMeritModal(id){let e=roster.employees.find(x=>String(x.id)===String(id));if(!e)return;showModal(`<div class="modal-head"><div class="modal-title">Merit Increase</div><button onclick="closeModal()">Close</button></div><div class="notice"><strong>${esc(fullName(e))}</strong><br>Current rate: ${money(e.rate)}</div><div class="form-grid"><div><label>Increase Type</label><select id="meritType" onchange="calcMeritPreview('${esc(id)}')"><option value="dollar">Dollar Amount</option><option value="percent">Percent</option></select></div><div><label>Increase</label><input id="meritAmt" type="number" step="0.01" value="0.00" oninput="calcMeritPreview('${esc(id)}')"></div><div><label>Effective Date</label><input id="meritDate" type="date" value="${new Date().toISOString().slice(0,10)}"></div><div><label>New Rate Preview</label><input id="meritPreview" readonly value="${money(e.rate)}"></div></div><div class="modal-actions"><button onclick="closeModal()">Cancel</button><button class="primary" onclick="confirmMerit('${esc(id)}')">Apply Increase</button></div>`)}
function calcMeritPreview(id){let e=roster.employees.find(x=>String(x.id)===String(id));if(!e)return;let base=Number(e.rate||0),amt=Number(val('meritAmt')||0),type=val('meritType');let next=type==='percent'?base+(base*amt/100):base+amt;let out=document.getElementById('meritPreview');if(out)out.value=money(next)}
function confirmMerit(id){let e=roster.employees.find(x=>String(x.id)===String(id));if(!e)return;let base=Number(e.rate||0),amt=Number(val('meritAmt')||0),type=val('meritType');let next=type==='percent'?base+(base*amt/100):base+amt;e.rate=Number(next.toFixed(2));e.dop=val('meritDate')||e.dop;roster.audit.push({at:new Date().toISOString(),user:env.user||'',action:'Merit increase',detail:fullName(e)+' '+money(base)+' -> '+money(e.rate)});saveRosterNow('merit').then(ok=>{if(ok){closeModal();safeRenderPages();toast('Merit increase applied')}})}
function openRosterPrintModal(){let cols=['Name','EID','Rank','Shift','Gate Shift','Rate','Type','RDO','Uniform','DOH','DOP','Notes'];showModal(`<div class="modal-head"><div class="modal-title">Print Roster</div><button onclick="closeModal()">Close</button></div><div class="notice">Choose columns for a printable roster. Current filters are respected unless you choose all employees.</div><div class="form-grid"><div class="full"><label>Rows to Print</label><select id="rpScope"><option value="filtered">Current filtered roster</option><option value="all">All employees</option></select></div><div class="full"><label>Columns</label><div class="day-grid">${cols.map(c=>`<label class="day-check"><input type="checkbox" class="rpCol" value="${c}" checked> ${c}</label>`).join('')}</div></div></div><div class="modal-actions"><button onclick="setRosterPrintCols(false)">Basic</button><button onclick="setRosterPrintCols(true)">All Columns</button><button onclick="closeModal()">Cancel</button><button class="primary" onclick="printRosterCustom()">Print</button></div>`)}
