function scheduleExportCss(){return `@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@400;600;700;800&family=Barlow:wght@400;500;600&display=swap');
:root { --red:#C0272D; --gold:#C6B273; --charcoal:#1e2330; --surface:#28303f; --surface2:#313b4d; --surface3:#3d4a5e; --border:#404d62; --text:#eef0f4; --text-muted:#8a96a8; --text-dim:#c4cad5; --orange:#e08a2f; }
* { box-sizing:border-box; } body { margin:0; font-family:'Barlow',sans-serif; background:var(--charcoal); color:var(--text); padding:24px; } .header { border-bottom:3px solid var(--red); padding:0 0 14px 0; margin-bottom:18px; display:flex; justify-content:space-between; align-items:flex-end; gap:16px; } .title { font-family:'Barlow Condensed',sans-serif; font-weight:800; font-size:30px; color:var(--gold); letter-spacing:1px; text-transform:uppercase; } .subtitle { font-size:12px; color:var(--text-muted); letter-spacing:.4px; margin-top:3px; } .actions { display:flex; gap:8px; } .btn { font-family:'Barlow Condensed',sans-serif; font-weight:700; font-size:13px; letter-spacing:.8px; text-transform:uppercase; padding:8px 14px; border-radius:4px; border:1px solid var(--border); background:transparent; color:var(--text-dim); cursor:pointer; } .schedule-section { margin-bottom:28px; break-inside:avoid; page-break-inside:avoid; } .section-head { font-family:'Barlow Condensed',sans-serif; font-weight:800; font-size:15px; letter-spacing:1px; text-transform:uppercase; color:var(--red); padding:8px 12px; background:var(--surface); border:1px solid var(--border); border-left:3px solid var(--red); border-radius:4px; margin-bottom:8px; display:block;} .table-wrap { overflow-x:auto; border-radius:6px; border:1px solid var(--border); } .schedule-grid { display:grid; grid-template-columns:120px repeat(7, 1fr); gap:1px; background:var(--border); border:1px solid var(--border); border-radius:6px; overflow:hidden; font-size:12px; min-width:900px; } .sch-head { background:var(--surface2); font-family:'Barlow Condensed',sans-serif; font-weight:700; font-size:11px; letter-spacing:1px; text-transform:uppercase; color:var(--gold); padding:8px 6px; text-align:center; } .sch-post { background:var(--surface2); color:var(--text-muted); font-family:'Barlow Condensed',sans-serif; font-weight:700; font-size:10px; letter-spacing:.5px; text-transform:uppercase; padding:8px 8px; display:flex; align-items:center; } .sch-cell { background:var(--surface); padding:5px 6px; text-align:center; position:relative; min-height:36px; } .sch-name { font-size:11px; color:var(--text-dim); line-height:1.3; } .sch-name.none { color:var(--surface3); font-style:italic; } .sch-name.open { color:var(--orange); font-style:italic; font-weight:600; } .sch-name.pending { color:var(--gold); font-style:italic; } .sch-closed { background:#161c28 !important; } .sch-rank-abbr { font-size:9px;font-family:'Barlow Condensed',sans-serif;font-weight:700;letter-spacing:.5px;opacity:.85;display:block;margin-top:1px; }
@media print { @page { size:landscape; margin:.35in; } body { background:white; color:#111; padding:0; } .actions { display:none; } .title { color:#111; } .subtitle { color:#444; } .section-head { color:#111; border-color:#999; background:#eee; } .table-wrap, .schedule-grid { border-color:#999; } .schedule-grid { gap:1px; background:#999; } .sch-head { background:#ddd; color:#111; } .sch-post { background:#eee; color:#111; } .sch-cell { background:#fff !important; color:#111; } * { -webkit-print-color-adjust:exact; print-color-adjust:exact; } }`}
function scheduleShareHtml(){
  const date=new Date();
  const dateStamp=date.toISOString().slice(0,10);
  const printedDate=date.toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric'});
  return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>PWADC Security Schedule - ${dateStamp}</title>
<style>
${scheduleExportCss()}

.audit-native-frame-wrap{border:1px solid var(--border);border-radius:10px;overflow:hidden;background:var(--surface);height:calc(100vh - 150px);min-height:720px}.audit-native-frame{width:100%;height:100%;border:0;background:#fff}.audit-action-note{margin-bottom:12px}
</style>
</head>
<body>
<div class="header"><div><div class="title">PWADC Security Master Schedule</div><div class="subtitle">Schedule-only snapshot exported ${printedDate}. Roster, pay, uniforms, analytics, and edit controls are not included.</div></div><div class="actions"><button class="btn" onclick="window.print()">Print</button></div></div>
${scheduleHtmlSnapshot()}
</body>
</html>`;
}
function exportScheduleOnly(){const html=scheduleShareHtml();const dateStamp=new Date().toISOString().slice(0,10);const blob=new Blob([html],{type:'text/html'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='PWADC_Security_Schedule_'+dateStamp+'.html';document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);toast('Exported schedule-only HTML for supervisors.')}
function printRosterSchedule(){const w=window.open('','_blank');if(!w){toast('Popup blocked. Allow popups to print schedule.');return;}w.document.write(scheduleShareHtml());w.document.close();setTimeout(()=>w.print(),350)}
function renderRosterTraining(){
  const topics=(roster.trainingTopics||[]).slice().sort((a,b)=>String(a.name||'').localeCompare(String(b.name||'')));
  const rows=trainingRows();
  const visibleRows=filteredTrainingRows(rows);
  const overdue=visibleRows.filter(r=>r.status==='Overdue').length;
  const dueSoon=visibleRows.filter(r=>r.status==='Due Soon').length;
  const noRecord=visibleRows.filter(r=>r.status==='No Record').length;
  return `<div class="training-toolbar"><div><div class="page-title">Training Tracker</div><div class="page-sub">Employees run down the left. Topics run across the top. Add/edit records from any cell.</div></div><div class="top-actions"><button onclick="openTrainingTopicModal()">+ Add Topic</button><button class="gold" onclick="openTrainingRecordModal()">+ Add Training Record</button><button onclick="printTrainingMatrix()">Print Training</button><button onclick="exportTrainingCSV()">Export Training CSV</button></div></div>
  <div class="grid cols-4"><div class="kpi"><div class="num">${topics.length}</div><div class="lbl">Topics</div></div><div class="kpi"><div class="num">${roster.trainingRecords.length}</div><div class="lbl">Records</div></div><div class="kpi"><div class="num schedule-risk">${overdue}</div><div class="lbl">Overdue</div></div><div class="kpi"><div class="num">${noRecord}</div><div class="lbl">No Record</div></div></div>
  <div class="training-filters"><div><label>Search</label><input id="trainingSearch" placeholder="Employee, topic, notes..." value="${esc(window._trainingSearch||'')}" oninput="window._trainingSearch=this.value;safeRenderPages()"></div><div><label>Topic</label><select id="trainingTopicFilter" onchange="window._trainingTopicFilter=this.value;safeRenderPages()"><option value="">All Topics</option>${topics.map(t=>`<option value="${esc(t.id)}" ${(window._trainingTopicFilter||'')==String(t.id)?'selected':''}>${esc(t.name)}</option>`).join('')}</select></div><div><label>Status</label><select id="trainingStatusFilter" onchange="window._trainingStatusFilter=this.value;safeRenderPages()"><option value="">All Statuses</option>${['Complete','Due Soon','Overdue','No Record'].map(x=>`<option value="${x}" ${(window._trainingStatusFilter||'')===x?'selected':''}>${x}</option>`).join('')}</select></div><div style="align-self:end"><button onclick="window._trainingSearch='';window._trainingTopicFilter='';window._trainingStatusFilter='';safeRenderPages()">Clear Filters</button></div></div>
  <div class="training-layout"><div class="card training-side-card"><div class="card-title">Training Topics</div>${renderTrainingTopicsList()}</div><div class="card"><div class="card-title">Training Matrix</div><div class="training-print-note">Status summary: ${overdue} overdue · ${dueSoon} due soon · ${noRecord} no record</div>${renderTrainingMatrix()}</div></div>`
}
function trainingRows(){const topics=(roster.trainingTopics||[]).slice().sort((a,b)=>String(a.name||'').localeCompare(String(b.name||'')));const emps=(roster.employees||[]).slice().sort((a,b)=>fullName(a).localeCompare(fullName(b)));let rows=[];for(const emp of emps){for(const topic of topics){const rec=latestTrainingRecord(emp.id,topic.id);const status=trainingStatus(rec,topic);rows.push({emp,topic,rec,status});}}return rows}
function filteredTrainingRows(rows){const q=(window._trainingSearch||'').toLowerCase();const topicFilter=String(window._trainingTopicFilter||'');const statusFilter=window._trainingStatusFilter||'';return rows.filter(r=>!topicFilter||String(r.topic.id)===topicFilter).filter(r=>!statusFilter||r.status===statusFilter).filter(r=>!q||(fullName(r.emp)+' '+(r.emp.eid||'')+' '+(r.emp.shift||'')+' '+(r.topic.name||'')+' '+((r.rec&&r.rec.notes)||'')).toLowerCase().includes(q))}
function renderTrainingTopicsList(){const topics=(roster.trainingTopics||[]).slice().sort((a,b)=>String(a.name||'').localeCompare(String(b.name||'')));if(!topics.length)return '<div class="training-empty">No topics yet. Add a topic to start tracking training.</div>';return topics.map(t=>`<div class="topic-card"><div><div class="topic-title">${esc(t.name)}</div><div class="topic-meta">${t.required!==false?'Required':'Optional'} · ${esc(intervalLabel(t.intervalDays))}${t.notes?'<br>'+esc(t.notes):''}</div></div><div class="td-actions"><button class="sm" onclick="openTrainingTopicModal('${esc(t.id)}')">Edit</button><button class="sm danger" onclick="deleteTrainingTopic('${esc(t.id)}')">Remove</button></div></div>`).join('')}
function renderTrainingMatrix(){let topics=(roster.trainingTopics||[]).slice().sort((a,b)=>String(a.name||'').localeCompare(String(b.name||'')));let emps=(roster.employees||[]).slice().sort((a,b)=>{const sa=shiftSortName(a.shift),sb=shiftSortName(b.shift);return sa.localeCompare(sb)||fullName(a).localeCompare(fullName(b));});const q=(window._trainingSearch||'').toLowerCase();const topicFilter=String(window._trainingTopicFilter||'');const statusFilter=window._trainingStatusFilter||'';if(topicFilter)topics=topics.filter(t=>String(t.id)===topicFilter);if(q){emps=emps.filter(emp=>{const empHit=(fullName(emp)+' '+(emp.eid||'')+' '+(emp.shift||'')).toLowerCase().includes(q);const trainHit=topics.some(topic=>{const rec=latestTrainingRecord(emp.id,topic.id);return ((topic.name||'')+' '+((rec&&rec.notes)||'')).toLowerCase().includes(q)});return empHit||trainHit;});}if(statusFilter){emps=emps.filter(emp=>topics.some(topic=>trainingStatus(latestTrainingRecord(emp.id,topic.id),topic)===statusFilter));}if(!topics.length)return '<div class="training-empty">No training topics match the current filter.</div>';if(!emps.length)return '<div class="training-empty">No employees match the current training filters.</div>';const groups={};for(const emp of emps){const key=trainingShiftGroup(emp.shift);groups[key]=groups[key]||[];groups[key].push(emp);}const order=['1st','2nd','3rd','GATE','W/E Gate','DOCK','Crosswalk','RECP','Other'];const keys=Object.keys(groups).sort((a,b)=>(order.indexOf(a)<0?99:order.indexOf(a))-(order.indexOf(b)<0?99:order.indexOf(b))||a.localeCompare(b));return keys.map(key=>`<div class="training-shift-block"><div class="training-shift-head"><span>${esc(trainingShiftLabel(key))}</span><small>${groups[key].length} employee(s)</small></div><div class="training-matrix-wrap"><table class="training-matrix"><thead><tr><th>Employee</th>${topics.map(t=>`<th class="training-topic-th">${esc(t.name)}<div style="font-size:10px;color:var(--muted);margin-top:3px">${t.required!==false?'Required':'Optional'} · ${esc(intervalLabel(t.intervalDays))}</div></th>`).join('')}</tr></thead><tbody>${groups[key].map(emp=>`<tr><td><strong>${esc(fullName(emp))}</strong><div style="font-size:11px;color:var(--muted);margin-top:2px">${esc(emp.shift||'')} ${emp.eid?'· '+esc(emp.eid):''}</div></td>${topics.map(topic=>renderTrainingCell(emp,topic,statusFilter)).join('')}</tr>`).join('')}</tbody></table></div></div>`).join('')}
function trainingShiftGroup(shift){const s=String(shift||'').trim();if(/^1st/i.test(s))return '1st';if(/^2nd/i.test(s))return '2nd';if(/^3rd/i.test(s))return '3rd';if(/w\/e gate/i.test(s))return 'W/E Gate';if(/gate/i.test(s))return 'GATE';if(/dock/i.test(s))return 'DOCK';if(/crosswalk/i.test(s))return 'Crosswalk';if(/recp|reception/i.test(s))return 'RECP';return s||'Other'}
function shiftSortName(shift){const order={'1st':'01','2nd':'02','3rd':'03','GATE':'04','W/E Gate':'05','DOCK':'06','Crosswalk':'07','RECP':'08','Other':'99'};const g=trainingShiftGroup(shift);return (order[g]||'98')+' '+g}
function trainingShiftLabel(key){return key==='RECP'?'Reception':key==='GATE'?'Gate':key==='DOCK'?'Dock':key}
function renderTrainingCell(emp,topic,statusFilter=''){const rec=latestTrainingRecord(emp.id,topic.id);const status=trainingStatus(rec,topic);const filteredClass=statusFilter&&status!==statusFilter?' training-filtered-out':'';const dates=rec?`<div class="training-dates">Completed: ${esc(fmtDate(rec.completed||''))}<br>Due: ${esc(fmtDate(rec.due||''))}${rec.notes?'<br>Notes: '+esc(rec.notes):''}</div>`:'<div class="training-dates">No completion recorded</div>';return `<td class="training-cell${filteredClass}"><div class="training-cell-inner">${trainingStatusBadge(status)}${dates}<div class="training-actions"><button class="sm" onclick="openTrainingRecordModal('${rec?esc(rec.id):''}','${esc(emp.id)}','${esc(topic.id)}')">${rec?'Edit':'Add'}</button>${rec?`<button class="sm danger" onclick="deleteTrainingRecord('${esc(rec.id)}')">Remove</button>`:''}</div></div></td>`}
function latestTrainingRecord(empId,topicId){return (roster.trainingRecords||[]).filter(r=>String(r.employeeId)===String(empId)&&String(r.topicId)===String(topicId)).sort((a,b)=>String(b.completed||'').localeCompare(String(a.completed||'')))[0]||null}
function trainingStatus(rec,topic){if(!rec)return 'No Record';if(!rec.due||!topic||!Number(topic.intervalDays))return 'Complete';const today=parseISO(new Date().toISOString().slice(0,10));const due=parseISO(rec.due);const diff=Math.ceil((due-today)/86400000);if(diff<0)return 'Overdue';if(diff<=30)return 'Due Soon';return 'Complete'}
function trainingStatusBadge(status){const cls=status==='Complete'?'training-complete':status==='Due Soon'?'training-due':status==='Overdue'?'training-overdue':'training-none';return `<span class="training-status ${cls}">${esc(status)}</span>`}
function intervalLabel(n){n=Number(n)||0;if(!n)return 'One-time';if(n===30)return '30 days';if(n===90)return '90 days';if(n===180)return '6 months';if(n===365)return 'Annual';if(n===730)return 'Every 2 years';return n+' days'}
function trainingTopicById(id){return (roster.trainingTopics||[]).find(t=>String(t.id)===String(id))}
function trainingRecordById(id){return (roster.trainingRecords||[]).find(r=>String(r.id)===String(id))}
function openTrainingTopicModal(id=''){const t=id?trainingTopicById(id):null;showModal(`<div class="modal-head"><div class="modal-title">${t?'Edit Training Topic':'Add Training Topic'}</div><button onclick="closeModal()">Close</button></div><div class="form-grid"><div class="full"><label>Topic Name</label><input id="trainTopicName" value="${esc(t&&t.name||'')}" placeholder="Gate Procedures, Post Orders Review"></div><div><label>Renewal Interval</label><select id="trainTopicInterval">${[[0,'One-time / no expiration'],[30,'30 days'],[90,'90 days'],[180,'6 months'],[365,'Annual'],[730,'Every 2 years']].map(([v,l])=>`<option value="${v}" ${Number(t&&t.intervalDays||365)===v?'selected':''}>${l}</option>`).join('')}</select></div><div><label>Required?</label><select id="trainTopicRequired"><option value="yes" ${!t||t.required!==false?'selected':''}>Yes</option><option value="no" ${t&&t.required===false?'selected':''}>No</option></select></div><div class="full"><label>Notes</label><input id="trainTopicNotes" value="${esc(t&&t.notes||'')}" placeholder="Optional standard or reminder note"></div></div><div class="modal-actions"><button onclick="closeModal()">Cancel</button><button class="primary" onclick="saveTrainingTopic('${esc(id)}')">Save Topic</button></div>`)}
function saveTrainingTopic(id=''){const name=val('trainTopicName').trim();if(!name){toast('Training topic name is required');return;}if((roster.trainingTopics||[]).some(t=>String(t.id)!==String(id)&&String(t.name||'').toLowerCase()===name.toLowerCase())){toast('That topic already exists');return;}const data={name,intervalDays:Number(val('trainTopicInterval'))||0,required:val('trainTopicRequired')!=='no',notes:val('trainTopicNotes').trim()};if(id){Object.assign(trainingTopicById(id),data);}else{roster.trainingTopics.push({id:roster.nextTrainingTopicId++, ...data});}saveRosterNow('training-topic').then(ok=>{if(ok){closeModal();safeRenderPages();toast('Training topic saved')}})}
function deleteTrainingTopic(id){const t=trainingTopicById(id);if(!t)return;const count=(roster.trainingRecords||[]).filter(r=>String(r.topicId)===String(id)).length;if(!confirm('Remove training topic "'+t.name+'"?'+(count?'\n\nThis will also remove '+count+' record(s).':'')))return;roster.trainingTopics=roster.trainingTopics.filter(x=>String(x.id)!==String(id));roster.trainingRecords=roster.trainingRecords.filter(r=>String(r.topicId)!==String(id));saveRoster('training-topic-remove');safeRenderPages();toast('Training topic removed')}
function openTrainingRecordModal(recordId='',empId='',topicId=''){const rec=recordId?trainingRecordById(recordId):null;const emps=(roster.employees||[]).slice().sort((a,b)=>fullName(a).localeCompare(fullName(b)));const topics=(roster.trainingTopics||[]).slice().sort((a,b)=>String(a.name||'').localeCompare(String(b.name||'')));if(!emps.length){toast('Add employees before adding training records');return;}if(!topics.length){toast('Add a topic before adding records');return;}const selEmp=rec?rec.employeeId:(empId||emps[0].id);const selTopic=rec?rec.topicId:(topicId||topics[0].id);showModal(`<div class="modal-head"><div class="modal-title">${rec?'Edit Training Record':'Add Training Record'}</div><button onclick="closeModal()">Close</button></div><div class="form-grid"><div class="full"><label>Employee</label><select id="trainRecEmp">${emps.map(e=>`<option value="${esc(e.id)}" ${String(selEmp)===String(e.id)?'selected':''}>${esc(fullName(e))}</option>`).join('')}</select></div><div class="full"><label>Topic</label><select id="trainRecTopic" onchange="trainingRecordDateChanged()">${topics.map(t=>`<option value="${esc(t.id)}" ${String(selTopic)===String(t.id)?'selected':''}>${esc(t.name)}</option>`).join('')}</select></div><div><label>Completed Date</label><input id="trainRecCompleted" type="date" value="${esc(rec&&rec.completed||new Date().toISOString().slice(0,10))}" onchange="trainingRecordDateChanged()"></div><div><label>Due / Expiration Date</label><input id="trainRecDue" type="date" value="${esc(rec&&rec.due||'')}"></div><div class="full"><label>Notes</label><input id="trainRecNotes" value="${esc(rec&&rec.notes||'')}" placeholder="Optional notes"></div></div><div class="modal-actions"><button onclick="closeModal()">Cancel</button><button class="primary" onclick="saveTrainingRecord('${esc(recordId)}')">Save Record</button></div>`);setTimeout(trainingRecordDateChanged,0)}
function trainingRecordDateChanged(){const completed=val('trainRecCompleted');const topic=trainingTopicById(val('trainRecTopic'));const due=document.getElementById('trainRecDue');if(due&&completed&&topic&&Number(topic.intervalDays))due.value=addDays(completed,Number(topic.intervalDays))}
function saveTrainingRecord(recordId=''){const employeeId=val('trainRecEmp'),topicId=val('trainRecTopic'),completed=val('trainRecCompleted'),due=val('trainRecDue'),notes=val('trainRecNotes').trim();if(!employeeId||!topicId||!completed){toast('Employee, topic, and completed date are required');return;}const data={employeeId,topicId,completed,due,notes};if(recordId){Object.assign(trainingRecordById(recordId),data);}else{roster.trainingRecords.push({id:roster.nextTrainingRecordId++, ...data});}saveRosterNow('training-record').then(ok=>{if(ok){closeModal();safeRenderPages();toast('Training record saved')}})}
function deleteTrainingRecord(id){if(!confirm('Remove this training record?'))return;roster.trainingRecords=roster.trainingRecords.filter(r=>String(r.id)!==String(id));saveRoster('training-record-remove');safeRenderPages();toast('Training record removed')}
function exportTrainingCSV(){const topics=(roster.trainingTopics||[]).slice().sort((a,b)=>String(a.name||'').localeCompare(String(b.name||'')));let rows=[['Employee','EID','Shift','Topic','Status','Completed','Due','Notes']];for(const emp of (roster.employees||[]).slice().sort((a,b)=>fullName(a).localeCompare(fullName(b)))){for(const topic of topics){const rec=latestTrainingRecord(emp.id,topic.id);rows.push([fullName(emp),emp.eid||'',emp.shift||'',topic.name||'',trainingStatus(rec,topic),rec&&rec.completed||'',rec&&rec.due||'',rec&&rec.notes||'']);}}downloadCSV('PWADC_Training_'+new Date().toISOString().slice(0,10)+'.csv',rows);toast('Exported training CSV')}
function printTrainingMatrix(){const topics=(roster.trainingTopics||[]).slice().sort((a,b)=>String(a.name||'').localeCompare(String(b.name||'')));const emps=(roster.employees||[]).slice().sort((a,b)=>fullName(a).localeCompare(fullName(b)));let html=`<div class="print-overlay" id="printOverlay"><div class="print-toolbar"><div><h2>PWADC Security Training Matrix</h2><div>${new Date().toLocaleString()} · ${topics.length} topic(s) · ${roster.trainingRecords.length} record(s)</div></div><div><button onclick="window.print()">Print</button> <button onclick="document.getElementById('printOverlay').remove()">Close</button></div></div><table class="print-table"><thead><tr><th>Employee</th>${topics.map(t=>`<th>${esc(t.name)}</th>`).join('')}</tr></thead><tbody>${emps.map(emp=>`<tr><td>${esc(fullName(emp))}<br>${esc(emp.shift||'')}</td>${topics.map(topic=>{const rec=latestTrainingRecord(emp.id,topic.id);return `<td>${esc(trainingStatus(rec,topic))}<br>${rec?('Completed: '+esc(fmtDate(rec.completed||''))+'<br>Due: '+esc(fmtDate(rec.due||''))):'No record'}</td>`}).join('')}</tr>`).join('')}</tbody></table></div>`;document.body.insertAdjacentHTML('beforeend',html);setTimeout(()=>window.print(),150)}
function renderRosterUniforms(){
  const eligible=(roster.employees||[]).filter(e=>!['ONIN','APS','Onin'].includes(e.type)&&!['ONIN','APS'].includes(e.rank));
  const SIZES=['XS','S','M','L','XL','2X','3X','4X','5X'];
  const items=['shirt','pants','jacket'];
  const itemLabel={shirt:'Shirts',pants:'Pants',jacket:'Jackets'};
  const itemSingular={shirt:'shirt',pants:'pants',jacket:'jacket'};
  const itemColor={shirt:'var(--red)',pants:'var(--orange)',jacket:'var(--blue)'};
  const statusText=v=>v==='issued'?'Issued':v==='ordered'?'Ordered':'Needed';
  const statusBadge=v=>`<span class="status-badge ${esc(v||'needed')}">${esc(statusText(v||'needed'))}</span>`;
  const needsOrder=(e,k)=>{let v=(e[k+'Status']||'').toLowerCase();return !v||v==='needed'};
  const isOrdered=(e,k)=>(e[k+'Status']||'').toLowerCase()==='ordered';
  const isIssued=(e,k)=>(e[k+'Status']||'').toLowerCase()==='issued';
  const personSort=(a,b)=>String(a.last||'').localeCompare(String(b.last||''))||String(a.first||'').localeCompare(String(b.first||''));
  const buildTotals=(empList,k)=>{let totals={};for(const e of empList){let sz=e[k]||'Unspecified';let q=uniformQty(e,k);totals[sz]=(totals[sz]||0)+q}return totals};
  const sizeCards=(totals,label)=>{let standard=SIZES.filter(sz=>totals[sz]).map(sz=>`<div class="uni-card"><div class="uni-size">${esc(sz)}</div><div class="uni-qty">${totals[sz]} ${esc(label)}</div></div>`).join('');let extra=Object.entries(totals).filter(([sz])=>!SIZES.includes(sz)).sort().map(([sz,qty])=>`<div class="uni-card"><div class="uni-size" style="font-size:15px">${esc(sz)}</div><div class="uni-qty">${qty} ${esc(label)}</div></div>`).join('');return (standard+extra)||'<p class="empty-note">No sizes on record for employees needing this item.</p>'};
  const table=(empList,k,statusMode)=>{if(!empList.length)return `<p class="empty-note">No ${esc(itemSingular[k])} currently marked ${esc(statusMode)}.</p>`;let rows=empList.map(e=>{let ft=(7-((e.rdo||[]).length||0))>=5;let q=uniformQty(e,k);let st=(e[k+'Status']||'needed').toLowerCase()||'needed';return `<tr><td><strong>${esc(fullName(e))}</strong></td><td>${rankBadge(e.rank)}</td><td><span class="shift-pill">${esc(e.shift||'')}</span>${e.gateShift?`<br><span class="mini-note">${esc(e.gateShift)}</span>`:''}</td><td>${statusBadge(st)}</td><td style="color:${ft?'var(--green)':'var(--gold)'};font-size:12px;font-weight:900">${ft?'FT':'PT'}</td><td><strong>${q}</strong></td><td><strong>${esc(e[k]||'—')}</strong></td></tr>`}).join('');return `<div class="table-wrap"><table class="wide-table"><thead><tr><th>Name</th><th>Rank</th><th>Shift</th><th>Status</th><th>FT/PT</th><th>Qty</th><th>Size</th></tr></thead><tbody>${rows}</tbody></table></div>`};
  const collapsible=(title,count,inner,open=false,cls='')=>`<details class="uniform-collapse ${esc(cls)}" ${open?'open':''}><summary><span>${esc(title)} <b>(${count})</b></span><span class="collapse-hint">Click to ${open?'collapse':'expand'}</span></summary><div class="collapse-body">${inner}</div></details>`;
  const block=k=>{let need=eligible.filter(e=>needsOrder(e,k)).sort(personSort);let ordered=eligible.filter(e=>isOrdered(e,k)).sort(personSort);let issued=eligible.filter(e=>isIssued(e,k)).sort(personSort);let totals=buildTotals(need,k);let color=itemColor[k];return `<div class="item-block"><div class="item-head" style="color:${color};border-left-color:${color}">${itemLabel[k]}</div>${collapsible('Needed / Sizes to Order',need.length,`<div class="sub-head">Sizes to order${k==='jacket'?' - jackets count as 1 per employee':''}</div><div class="uniform-summary">${sizeCards(totals,k==='jacket'?'jackets':itemSingular[k]+'s')}</div><div class="sub-head">Who needs ${itemSingular[k]}s</div>${table(need,k,'needed')}`,true,'needed')}${collapsible('Already Ordered',ordered.length,table(ordered,k,'ordered'),false,'ordered')}${collapsible('Issued',issued.length,table(issued,k,'issued'),false,'issued')}</div>`};
  let shirtNeed=eligible.filter(e=>needsOrder(e,'shirt')).length;
  let pantsNeed=eligible.filter(e=>needsOrder(e,'pants')).length;
  let jacketNeed=eligible.filter(e=>needsOrder(e,'jacket')).length;
  return `<div class="uniform-original"><div class="uniform-toolbar"><div><div class="page-title">Uniform Orders</div><div class="page-sub">5 sets for full-time, 3 sets for part-time. ONIN / APS excluded. Jackets count as 1 per employee.</div></div><div class="top-actions"><button onclick="printUniformOrderSheet()">Print Order Sheet</button><button onclick="exportUniformCSV()">Export Uniform CSV</button></div></div><div class="stat-strip"><div class="stat-card"><div class="stat-value">${shirtNeed}</div><div class="stat-label">Shirts to Order</div></div><div class="stat-card orange"><div class="stat-value">${pantsNeed}</div><div class="stat-label">Pants to Order</div></div><div class="stat-card blue"><div class="stat-value">${jacketNeed}</div><div class="stat-label">Jackets to Order</div></div><div class="stat-card gold"><div class="stat-value">${eligible.length}</div><div class="stat-label">Eligible Staff</div></div></div>${items.map(block).join('')}</div>`
}
function renderRosterAnalytics(){
  const byShift=countBy(roster.employees,e=>e.shift||'Blank');
  const byRank=countBy(roster.employees,e=>e.rank||'Blank');
  const byType=countBy(roster.employees,e=>e.type||'Blank');
  const sched=scheduleMetrics();
  const openUniform=roster.employees.reduce((n,e)=>n+['shirt','pants','jacket'].filter(k=>(e[k+'Status']||'')&&e[k+'Status']!=='issued').length,0);
  const topShift=Object.entries(byShift).sort((a,b)=>b[1]-a[1])[0]||['-',0];
  return `<div class="analytics-toolbar"><div><div class="page-title">Labor Analytics</div><div class="page-sub">Headcount, schedule hours, open slots, FTE, and estimated weekly labor cost from the live roster schedule.</div></div><div class="top-actions"><button onclick="printAnalytics()">Print Analytics</button><button onclick="exportAnalyticsCSV()">Export Analytics CSV</button></div></div>
  <div class="grid cols-4"><div class="kpi"><div class="num">${roster.employees.length}</div><div class="lbl">Employees</div></div><div class="kpi"><div class="num">${sched.hours}</div><div class="lbl">Scheduled HPW</div></div><div class="kpi"><div class="num">${sched.fte.toFixed(1)}</div><div class="lbl">FTE Equivalent</div></div><div class="kpi"><div class="num schedule-risk">${sched.open}</div><div class="lbl">Open Slots</div></div></div>
  <div class="grid cols-2"><div class="card"><div class="card-title">Headcount by Shift</div>${analyticsBars(byShift)}</div><div class="card"><div class="card-title">Headcount by Rank</div>${analyticsBars(byRank)}</div><div class="card"><div class="card-title">Employment Type</div>${analyticsBars(byType)}</div><div class="card"><div class="card-title">Schedule Cost Snapshot</div><div class="analytics-money">${money(sched.cost)} / week</div><div class="health-row"><span>Most staffed shift</span><span class="ok">${esc(topShift[0])} · ${topShift[1]}</span></div><div class="health-row"><span>Uniform needs/orders</span><span class="warn">${openUniform}</span></div><div class="health-row"><span>Unmatched schedule names</span><span class="warn">${sched.unmatched}</span></div></div></div>
  <div class="card"><div class="card-title">Schedule Hours by Section</div><div class="table-wrap"><table class="wide-table"><thead><tr><th>Section</th><th>Rows</th><th>Assigned Slots</th><th>Open Slots</th><th>HPW</th><th>Est. Weekly Cost</th></tr></thead><tbody>${Object.values(sched.sections).map(x=>`<tr><td>${esc(x.section)}</td><td>${x.rows}</td><td>${x.assigned}</td><td class="schedule-risk">${x.open}</td><td>${x.hours}</td><td>${money(x.cost)}</td></tr>`).join('')}</tbody></table></div></div>`
}
function titleCase(s){return (s||'').charAt(0).toUpperCase()+(s||'').slice(1)}
function uniformQty(e,item){if(item==='jacket')return 1;let days=7-((e.rdo||[]).length||0);return days>=5?5:3}
function getUniformItems(mode='open'){let out=[];for(const e of roster.employees){if(['ONIN','APS','Onin'].includes(e.type)||['ONIN','APS'].includes(e.rank))continue;for(const k of ['shirt','pants','jacket']){let status=(e[k+'Status']||'').toLowerCase();if(!status)status='needed';if(mode==='open'&&status==='issued')continue;if(mode!=='all'&&mode!=='open'&&status!==mode)continue;out.push({employee:fullName(e),rank:e.rank,shift:e.shift,item:k,size:e[k]||'Unspecified',status,qty:uniformQty(e,k)})}}return out}
function getUniformOpenItems(){return getUniformItems('open')}
function aggregateUniforms(items){const aggregate={};for(const i of items){const key=i.item+'|'+i.size+'|'+i.status;if(!aggregate[key])aggregate[key]={item:i.item,size:i.size,status:i.status,qty:0,people:0};aggregate[key].qty+=i.qty;aggregate[key].people+=1}return Object.values(aggregate).sort((a,b)=>(a.status+a.item+a.size).localeCompare(b.status+b.item+b.size))}
function schedulePersonName(raw){let v=(raw||'').trim();if(!v||['none','closed','open','pending'].includes(v.toLowerCase()))return '';let parts=v.split(/\s+/);let first=parts[0].replace(/[^A-Za-z]/g,'').toUpperCase();if(['SUPV','PSO','SO','SSO','LSO','ONIN','APS','RECEP','ST'].includes(first))v=parts.slice(1).join(' ');return v.trim()}
function findRosterByScheduleName(raw){let nm=schedulePersonName(raw).toLowerCase();if(!nm)return null;return roster.employees.find(e=>fullName(e).toLowerCase()===nm)||roster.employees.find(e=>nm.includes(e.last.toLowerCase())&&nm.includes(e.first.toLowerCase()))||null}
function scheduleMetrics(){let out={hours:0,cost:0,open:0,unmatched:0,fte:0,sections:{}};for(const row of (roster.schedule||[])){let sec=row.section||'Unassigned';let bucket=out.sections[sec]||(out.sections[sec]={section:sec,rows:0,assigned:0,open:0,hours:0,cost:0});bucket.rows++;for(const cell of (row.days||[])){let val=(cell||'').trim();let low=val.toLowerCase();if(!val||low==='none'||low==='closed')continue;if(low==='open'||low==='pending'){out.open++;bucket.open++;continue;}let hrs=Number(row.hrs||8);out.hours+=hrs;bucket.hours+=hrs;bucket.assigned++;let emp=findRosterByScheduleName(val);if(emp){let cost=Number(emp.rate||0)*hrs;out.cost+=cost;bucket.cost+=cost}else out.unmatched++;}}out.fte=out.hours/40;return out}
function analyticsBars(obj){let entries=Object.entries(obj).sort((a,b)=>b[1]-a[1]);let max=Math.max(1,...entries.map(x=>x[1]));return `<div class="analytics-list">${entries.map(([k,v])=>`<div class="analytics-bar"><span>${esc(k)}</span><div class="bar-track"><div class="bar-fill" style="width:${Math.round(v/max*100)}%"></div></div><strong>${v}</strong></div>`).join('')}</div>`}
function printUniformOrderSheet(){let items=getUniformItems('all');let rows=['needed','ordered','issued'].map(st=>`<tr><th colspan="7" style="text-align:left;background:#e5e7eb;">${st.toUpperCase()}</th></tr>`+items.filter(i=>i.status===st).map(i=>`<tr><td>${esc(i.employee)}</td><td>${esc(i.rank)}</td><td>${esc(i.shift)}</td><td>${esc(titleCase(i.item))}</td><td>${esc(i.size)}</td><td>${esc(i.status)}</td><td>${i.qty}</td></tr>`).join('')).join('');let html=`<div class="print-overlay" id="printOverlay"><div class="print-toolbar"><div><h2>PWADC Security Uniform Accountability</h2><div>${new Date().toLocaleString()} · needed, ordered, and issued</div></div><div><button onclick="window.print()">Print</button> <button onclick="document.getElementById('printOverlay').remove()">Close</button></div></div><table class="print-table"><thead><tr><th>Employee</th><th>Rank</th><th>Shift</th><th>Item</th><th>Size</th><th>Status</th><th>Qty</th></tr></thead><tbody>${rows}</tbody></table></div>`;document.body.insertAdjacentHTML('beforeend',html);setTimeout(()=>window.print(),150)}
function exportUniformCSV(){let rows=[['Employee','Rank','Shift','Item','Size','Status','Qty'],...getUniformItems('all').map(i=>[i.employee,i.rank,i.shift,titleCase(i.item),i.size,i.status,i.qty])];downloadCSV('PWADC_Uniforms_'+new Date().toISOString().slice(0,10)+'.csv',rows)}
function exportAnalyticsCSV(){let m=scheduleMetrics();let rows=[['Metric','Value'],['Employees',roster.employees.length],['Scheduled HPW',m.hours],['FTE',m.fte.toFixed(2)],['Open Slots',m.open],['Estimated Weekly Cost',m.cost.toFixed(2)],[],['Section','Rows','Assigned Slots','Open Slots','HPW','Cost'],...Object.values(m.sections).map(x=>[x.section,x.rows,x.assigned,x.open,x.hours,x.cost.toFixed(2)])];downloadCSV('PWADC_Roster_Analytics_'+new Date().toISOString().slice(0,10)+'.csv',rows)}
function printAnalytics(){let m=scheduleMetrics();let rows=Object.values(m.sections);let html=`<div class="print-overlay" id="printOverlay"><div class="print-toolbar"><div><h2>PWADC Security Labor Analytics</h2><div>${new Date().toLocaleString()} · HPW ${m.hours} · FTE ${m.fte.toFixed(1)} · Open Slots ${m.open}</div></div><div><button onclick="window.print()">Print</button> <button onclick="document.getElementById('printOverlay').remove()">Close</button></div></div><table class="print-table"><thead><tr><th>Section</th><th>Rows</th><th>Assigned</th><th>Open</th><th>HPW</th><th>Cost</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.section)}</td><td>${x.rows}</td><td>${x.assigned}</td><td>${x.open}</td><td>${x.hours}</td><td>${money(x.cost)}</td></tr>`).join('')}</tbody></table></div>`;document.body.insertAdjacentHTML('beforeend',html);setTimeout(()=>window.print(),150)}
function downloadCSV(name,rows){let csv=rows.map(r=>r.map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(',')).join('\n');let blob=new Blob([csv],{type:'text/csv'});let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}

function countBy(arr,fn){let o={};for(const x of arr){let k=fn(x);o[k]=(o[k]||0)+1}return o}
function val(id){let el=document.getElementById(id);return el?el.value:''}
function showModal(html){
  closeModal();
  let d=document.createElement('div');
  d.className='modal-backdrop';d.id='modalBackdrop';
  d.innerHTML='<div class="modal-card" onclick="event.stopPropagation()">'+html+'</div>';
  d.addEventListener('click',()=>closeModal());
  document.body.appendChild(d);
  setTimeout(()=>{let f=d.querySelector('input,select,textarea,button');if(f&&f.focus)f.focus();},30);
}
function closeModal(){let d=document.getElementById('modalBackdrop');if(d)d.remove()}
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.getElementById('modalBackdrop'))closeModal();});
async function importRosterJSON(input){const file=input&&input.files&&input.files[0];if(!file)return;try{const text=await file.text();const data=JSON.parse(text);if(!Array.isArray(data.employees)||!Array.isArray(data.schedule))throw new Error('File does not look like a PWADC roster/staff JSON export.');roster=data;normalizeRoster();roster.audit.push({at:new Date().toISOString(),user:env.user||'',action:'Roster JSON imported',detail:file.name});await createRosterBackup();await saveRosterNow('import');await syncAttendanceFromRoster(false);safeRenderPages();toast('Imported roster JSON and synced Attendance: '+file.name)}catch(e){toast('Roster import failed: '+e.message)}finally{if(input)input.value=''}}
async function reloadPackagedRosterData(){if(!confirm('Replace current shared roster data with the packaged latest roster JSON? A backup will be created first.'))return;try{await createRosterBackup();let r=await SuiteBridge.send('suite:resetModuleFromSeed',{}, {module:'roster'});let raw=r.data;roster=typeof raw==='string'?JSON.parse(raw||'{}'):(raw||{});normalizeRoster();safeRenderPages();toast('Loaded packaged latest roster JSON')}catch(e){toast('Roster reload failed: '+e.message)}}
async function createRosterBackup(){try{await SuiteBridge.send('suite:createBackup',roster,{module:'roster'});toast('Roster backup created')}catch(e){toast('Roster backup failed: '+e.message)}}
function exportRosterCSV(){let rows=['Last,First,EID,Rank,Shift,Gate Shift,Rate,Type,DOH,DOP,RDO,Shirt,Shirt Status,Pants,Pants Status,Jacket,Jacket Status,Notes'];for(const e of roster.employees){rows.push([e.last,e.first,e.eid,e.rank,e.shift,e.gateShift,e.rate,e.type,e.doh,e.dop,(e.rdo||[]).join('/'),e.shirt,e.shirtStatus,e.pants,e.pantsStatus,e.jacket,e.jacketStatus,e.notes].map(x=>'"'+String(x||'').replace(/"/g,'""')+'"').join(','))}SuiteBridge.send('suite:writeExport',rows.join('\n'),{module:'roster',fileName:'roster-export-'+new Date().toISOString().slice(0,10)+'.csv'}).then(()=>toast('Roster CSV exported')).catch(e=>toast('Roster export failed: '+e.message))}
function renderAttendance(){return `<div class="page-head"><div><div class="page-title">Attendance</div><div class="page-sub">Fast daily entry, grid review, exceptions, shared JSON autosave</div></div><div><button onclick="document.getElementById('attendanceImportFile').click()">Import JSON</button> <button onclick="reloadPackagedAttendanceData()">Use Packaged Latest JSON</button> <button onclick="createAttendanceBackup()">Backup Now</button> <button onclick="exportAttendanceCSV()">Export CSV</button><input id="attendanceImportFile" type="file" accept=".json,application/json" class="hidden" onchange="importAttendanceJSON(this)"></div></div><div class="subnav">${['daily','grid','exceptions','audit'].map(v=>`<button class="${activeAttView===v?'active':''}" onclick="activeAttView='${v}';safeRenderPages()">${v==='daily'?'Daily Entry':v==='grid'?'90-Day Grid':v==='exceptions'?'Exceptions':'Audit Log'}</button>`).join('')}</div>${activeAttView==='daily'?renderDaily():activeAttView==='grid'?renderGrid():activeAttView==='exceptions'?renderExceptions():renderAudit()}`}
function shiftRank(shift){let i=SHIFT_ORDER.indexOf(shift||'');return i>=0?i:99}
function sortedEmployees(){return activeAttendanceEmployees().slice().sort((a,b)=>shiftRank(a.shift)-shiftRank(b.shift)||(a.shift||'').localeCompare(b.shift||'')||(a.name||'').localeCompare(b.name||''))}
function currentRows(){let rows=sortedEmployees();if(entryShift!=='All')rows=rows.filter(e=>e.shift===entryShift);if(showBlanks)rows=rows.filter(e=>!getCode(e.id,entryDate));return rows}
function groupRowsByShift(rows){const groups=[];const map={};for(const e of rows){const sh=e.shift||'Unassigned';if(!map[sh]){map[sh]=[];groups.push({shift:sh,rows:map[sh]});}map[sh].push(e);}groups.sort((a,b)=>shiftRank(a.shift)-shiftRank(b.shift)||a.shift.localeCompare(b.shift));return groups}
function dailyCounts(rows){const dow=parseISO(entryDate).getDay();let entered=0,blank=0,rdo=0;for(const e of rows){if((e.rdos||[]).includes(dow))rdo++;if(getCode(e.id,entryDate))entered++;else blank++;}return{entered,blank,rdo,total:rows.length}}
function getCode(id,date){return (attendance.attendance[id]&&attendance.attendance[id][date])||''}function setCode(id,date,code){attendance.attendance[id]=attendance.attendance[id]||{};if(code)attendance.attendance[id][date]=code;else delete attendance.attendance[id][date];audit('Attendance code set',`${id} ${date} ${code||'blank'}`);saveAttendance()}
function autoFillRdosForDate(date){let changed=0;const dow=parseISO(date).getDay();for(const e of activeAttendanceEmployees()){if((e.rdos||[]).includes(dow)&&!getCode(e.id,date)){attendance.attendance[e.id]=attendance.attendance[e.id]||{};attendance.attendance[e.id][date]='O';changed++;}}if(changed){audit('RDO auto-filled',changed+' blank RDO(s) set to O for '+date);saveAttendance('rdo-auto');}}
function renderDaily(){autoFillRdosForDate(entryDate);const shifts=['All',...SHIFT_ORDER.filter(sh=>activeAttendanceEmployees().some(e=>e.shift===sh)),...Array.from(new Set(activeAttendanceEmployees().map(e=>e.shift).filter(Boolean))).filter(sh=>!SHIFT_ORDER.includes(sh))];const rows=currentRows();const counts=dailyCounts(rows);const groups=groupRowsByShift(rows);return `<div class="card"><div class="card-title">Daily Entry Command Pad</div><div class="toolbar"><div><label>Date</label><input type="date" value="${entryDate}" onchange="entryDate=this.value;safeRenderPages()"></div><div><label>Shift</label><select onchange="entryShift=this.value;safeRenderPages()">${shifts.map(s=>`<option ${entryShift===s?'selected':''}>${s}</option>`).join('')}</select></div><div><label>Active Code</label><div class="quick-codes">${CODES.map(c=>`<button class="code-btn ${c[0]} ${activeCode===c[0]?'active':''}" title="${c[1]}" onclick="activeCode='${c[0]}';safeRenderPages()">${c[0]}</button>`).join('')}</div></div></div><div class="toolbar"><button class="primary" onclick="markScheduledPresent()">Mark Scheduled Present</button><button onclick="markRdosOff()">Mark RDOs Off</button><button onclick="copyPreviousDay()">Copy Previous Day</button><button onclick="showBlanks=!showBlanks;safeRenderPages()">${showBlanks?'Show All':'Show Blanks Only'}</button><button class="danger" onclick="clearDay()">Clear Day</button></div><div class="notice"><div>Daily Entry is grouped by shift. Use the code buttons beside each employee, or click an employee and type a code from the keyboard. Blank RDOs are automatically set to O.</div><div class="keyboard-help"><strong>Keyboard:</strong> P, T, A=AL, L=LE, W=UE, E, U, V, O, F=FL, N=NE. Number keys 1-0 also map left-to-right across the code row.</div></div><div class="daily-status"><span class="chip">${counts.total} visible</span><span class="chip">${counts.entered} entered</span><span class="chip">${counts.blank} blank</span><span class="chip">${counts.rdo} RDO</span></div></div><div class="people-list">${groups.map(g=>renderShiftDailyGroup(g)).join('')}</div>`}
function renderShiftDailyGroup(g){const c=dailyCounts(g.rows);return `<section class="shift-section"><div class="shift-head"><strong>${esc(g.shift)}</strong><span>${c.total} people · ${c.entered} entered · ${c.blank} blank · ${c.rdo} RDO</span></div><div class="shift-body">${g.rows.map(renderDailyRow).join('')}</div></section>`}
function renderDailyRow(e){const c=getCode(e.id,entryDate);const isRdo=e.rdos&&e.rdos.includes(parseISO(entryDate).getDay());const selected=selectedEntryEmpId===e.id;return `<div class="person-row ${selected?'selected':''} ${isRdo?'rdo-auto':''}" tabindex="0" onclick="selectedEntryEmpId='${esc(e.id)}';safeRenderPages()" onfocus="selectedEntryEmpId='${esc(e.id)}';safeRenderPages()"><div class="person-name"><strong>${esc(e.name)}</strong><span>${esc(e.title)} · ${esc(e.shift)}</span></div><div class="row-code-pad">${CODES.map(code=>`<button class="row-code-btn ${code[0]} ${c===code[0]?'active':''}" title="${esc(code[1])}" onclick="event.stopPropagation();selectedEntryEmpId='${esc(e.id)}';setCode('${esc(e.id)}','${entryDate}','${code[0]}');safeRenderPages()">${code[0]}</button>`).join('')}</div><div class="row-status"><span class="badge ${esc(c)}">${esc(c||'Blank')}</span>${isRdo?'<span class="chip">RDO</span>':''}</div><div><button class="sm" onclick="event.stopPropagation();editNote('${esc(e.id)}','${entryDate}')">Note</button></div></div>`}
function last7(id){let out=[];for(let i=6;i>=0;i--){let d=addDays(entryDate,-i),c=getCode(id,d);out.push(`<span class="badge ${esc(c)}" title="${fmt(d)}">${esc(c||'-')}</span>`)}return out.join(' ')}function editNote(id,date){const k=id+'|'+date;let n=prompt('Attendance note:',attendance.notes[k]||'');if(n===null)return;if(n.trim())attendance.notes[k]=n.trim();else delete attendance.notes[k];audit('Attendance note updated',k);saveAttendance();safeRenderPages()}
function markScheduledPresent(){for(const e of currentRows()){const dow=parseISO(entryDate).getDay();if(!(e.rdos||[]).includes(dow)&&!getCode(e.id,entryDate))setCode(e.id,entryDate,'P')}toast('Scheduled blanks marked Present');safeRenderPages()}function markRdosOff(){for(const e of currentRows()){const dow=parseISO(entryDate).getDay();if((e.rdos||[]).includes(dow))setCode(e.id,entryDate,'O')}toast('RDOs marked Off');safeRenderPages()}function copyPreviousDay(){const prev=addDays(entryDate,-1);for(const e of currentRows()){const c=getCode(e.id,prev);if(c)setCode(e.id,entryDate,c)}toast('Copied previous day');safeRenderPages()}function clearDay(){if(!confirm('Clear visible entries for '+entryDate+'?'))return;for(const e of currentRows())setCode(e.id,entryDate,'');safeRenderPages()}
function getDates(){let arr=[];for(let d=addDays(gridEnd,-89);d<=gridEnd;d=addDays(d,1))arr.push(d);return arr.reverse()}function renderGrid(){const dates=getDates();const rows=currentRows();if((!selectedGridEmpId||!rows.some(e=>String(e.id)===String(selectedGridEmpId)))&&rows.length)selectedGridEmpId=rows[0].id;if(!selectedGridDate)selectedGridDate=dates[0]||gridEnd;return `<div class="card"><div class="card-title">90-Day Grid</div><div class="toolbar"><div><label>Ending Date</label><input type="date" value="${gridEnd}" onchange="gridEnd=this.value;selectedGridDate='';safeRenderPages()"></div><div><label>Shift</label><select onchange="entryShift=this.value;selectedGridEmpId='';safeRenderPages()">${['All',...SHIFT_ORDER.filter(sh=>activeAttendanceEmployees().some(e=>e.shift===sh)),...Array.from(new Set(activeAttendanceEmployees().map(e=>e.shift).filter(Boolean))).filter(sh=>!SHIFT_ORDER.includes(sh))].map(s=>`<option ${entryShift===s?'selected':''}>${s}</option>`).join('')}</select></div></div><div class="notice">Newest date is on the left. Click a cell, then press a keyboard shortcut to update it. Cell edits no longer re-render the full page.</div><div class="grid-key-help"><strong>Keyboard:</strong> P Present · T Late · A Approved Late · L Left Early · W Unauthorized Early · E Excused · U Unexcused · V Vacation · O Off/RDO · F FL · N Not Employed · Delete/Backspace Clear · Arrow keys move selected cell</div></div><div class="table-wrap" id="attendanceGridWrap"><table><thead><tr><th class="name">Employee</th>${dates.map(d=>`<th class="${d===new Date().toISOString().slice(0,10)?'today':''}">${fmt(d)}<br>${DAYS[parseISO(d).getDay()]}</th>`).join('')}</tr></thead><tbody>${rows.map(e=>`<tr><td class="name"><strong>${esc(e.name)}</strong><br><small>${esc(e.shift)} · ${esc(e.title)}</small></td>${dates.map(d=>{let c=getCode(e.id,d);let selected=String(selectedGridEmpId)===String(e.id)&&selectedGridDate===d;return `<td class="att-grid-cell ${parseISO(d).getDay()%6===0?'weekend':''} ${selected?'selected':''}" data-emp="${esc(e.id)}" data-date="${esc(d)}" onclick="selectGridCell('${esc(e.id)}','${esc(d)}')" ondblclick="selectGridCell('${esc(e.id)}','${esc(d)}');applyGridKeyboardCode(activeCode)" title="Click to select. Double-click applies active code. Keyboard shortcuts update selected cell."><span class="badge ${esc(c)}">${esc(c||'')}</span></td>`}).join('')}</tr>`).join('')}</tbody></table></div>`}
function findGridCell(empId,date){return Array.from(document.querySelectorAll('.att-grid-cell')).find(cell=>String(cell.dataset.emp)===String(empId)&&String(cell.dataset.date)===String(date))||null}
function updateGridSelectedDom(){document.querySelectorAll('.att-grid-cell.selected').forEach(x=>x.classList.remove('selected'));const cell=findGridCell(selectedGridEmpId,selectedGridDate);if(cell)cell.classList.add('selected')}
function updateGridCellDom(empId,date,code){const cell=findGridCell(empId,date);if(!cell)return;let b=cell.querySelector('.badge');if(!b){b=document.createElement('span');cell.appendChild(b)}b.className='badge '+(code||'');b.textContent=code||'';cell.classList.add('cell-flash');setTimeout(()=>cell.classList.remove('cell-flash'),350)}
function selectGridCell(empId,date){selectedGridEmpId=empId;selectedGridDate=date;updateGridSelectedDom()}
function moveGridSelection(rowDelta,colDelta){const dates=getDates();const rows=currentRows();if(!rows.length||!dates.length)return;let r=rows.findIndex(e=>String(e.id)===String(selectedGridEmpId));if(r<0)r=0;let c=dates.indexOf(selectedGridDate);if(c<0)c=0;r=Math.max(0,Math.min(rows.length-1,r+rowDelta));c=Math.max(0,Math.min(dates.length-1,c+colDelta));selectGridCell(rows[r].id,dates[c])}
function applyGridKeyboardCode(code){if(!selectedGridEmpId||!selectedGridDate){const rows=currentRows();const dates=getDates();if(rows.length)selectedGridEmpId=rows[0].id;if(dates.length)selectedGridDate=dates[0]}if(!selectedGridEmpId||!selectedGridDate)return;if(code==='CLEAR'){if(attendance.attendance[selectedGridEmpId])delete attendance.attendance[selectedGridEmpId][selectedGridDate];audit('Grid cell cleared',selectedGridEmpId+' · '+selectedGridDate);updateGridCellDom(selectedGridEmpId,selectedGridDate,'');saveAttendance();return;}activeCode=code;setCode(selectedGridEmpId,selectedGridDate,code);updateGridCellDom(selectedGridEmpId,selectedGridDate,code)}
function issueDateLabel(items){return (items||[]).slice().sort((a,b)=>b.date.localeCompare(a.date)).map(x=>fmt(x.date)+' '+x.code).join(', ')||'No dates'}function flagKey(empId,type,periodKey){return `${empId}|${type}|${periodKey}`}function computeFlags(){const dates=getDates(),flags=[],s=attendance.settings;for(const e of activeAttendanceEmployees()){let issues=[],counts={week:{},month:{},dow:{}},disc=[],occ=[];for(const d of dates){const c=getCode(e.id,d),dt=parseISO(d),wk=weekKey(dt),mo=d.slice(0,7),dow=DAYS[dt.getDay()];if(c==='U')issues.push({type:'Unexcused',sev:'critical',periodKey:d,msg:`Unexcused absence on ${fmt(d)}`,issueDates:[{date:d,code:c}]});if(c==='UE')issues.push({type:'Unauthorized Early',sev:'high',periodKey:d,msg:`Unauthorized early departure on ${fmt(d)}`,issueDates:[{date:d,code:c}]});if(OCC_CODES.has(c)){disc.push({date:d,code:c});occ.push({date:d,code:c})}if(PATTERN_CODES.has(c)){let item={date:d,code:c};counts.week[wk]=counts.week[wk]||[];counts.week[wk].push(item);counts.month[mo]=counts.month[mo]||[];counts.month[mo].push(item);counts.dow[dow]=counts.dow[dow]||[];counts.dow[dow].push(item)}}if(disc.length>=s.rollingThreshold)issues.push({type:'90-Day',sev:'critical',periodKey:`rolling-${dates[dates.length-1]}-${dates[0]}`,msg:`${disc.length} discipline occurrence(s) in 90 days`,issueDates:disc});for(const [k,it] of Object.entries(counts.week))if(it.length>=s.weekThreshold)issues.push({type:'Weekly',sev:'high',periodKey:k,msg:`${it.length} attendance issue(s) in week of ${k}`,issueDates:it});for(const [k,it] of Object.entries(counts.month))if(it.length>=s.monthThreshold)issues.push({type:'Monthly',sev:'high',periodKey:k,msg:`${it.length} attendance issue(s) in ${k}`,issueDates:it});for(const [k,it] of Object.entries(counts.dow))if(it.length>=s.patternThreshold)issues.push({type:'Pattern',sev:'medium',periodKey:k,msg:`${it.length} attendance issue(s) on ${k}s`,issueDates:it});if(occ.length>=6)issues.push({type:'Occurrences',sev:'critical',periodKey:`occ-${dates[dates.length-1]}-${dates[0]}`,msg:`${occ.length} discipline occurrence(s) in 90 days`,issueDates:occ});else if(occ.length>=4)issues.push({type:'Occurrences',sev:'high',periodKey:`occ-${dates[dates.length-1]}-${dates[0]}`,msg:`${occ.length} discipline occurrence(s) in 90 days`,issueDates:occ});for(const iss of issues){const k=flagKey(e.id,iss.type,iss.periodKey),a=attendance.flagActions[k];flags.push({...iss,emp:e,key:k,addressed:!!a,action:a||null})}}return flags}
function buildBuckets(flags){const order=['T','AL','LE','E','U','UE','V','GEN'],map={};for(const f of flags){for(const it of (f.issueDates&&f.issueDates.length?f.issueDates:[{code:'GEN',date:f.periodKey}])){const code=order.includes(it.code)?it.code:'GEN';map[code]=map[code]||{code,dates:{},flags:[]};if(it.date)map[code].dates[it.date]=true;if(!map[code].flags.some(x=>x.key===f.key))map[code].flags.push(f)}}return Object.values(map).sort((a,b)=>order.indexOf(a.code)-order.indexOf(b.code)).map(b=>({...b,dateList:Object.keys(b.dates).sort((a,b)=>b.localeCompare(a))}))}
function renderExceptions(){const flags=computeFlags();const open=flags.filter(f=>!f.addressed);let groups={};for(const f of flags){groups[f.emp.id]=groups[f.emp.id]||{emp:f.emp,flags:[]};groups[f.emp.id].flags.push(f)}let list=Object.values(groups).sort((a,b)=>b.flags.filter(f=>!f.addressed).length-a.flags.filter(f=>!f.addressed).length||a.emp.name.localeCompare(b.emp.name));return `<div class="grid cols-3"><div class="kpi"><div class="num">${open.filter(f=>f.sev==='critical').length}</div><div class="lbl">Critical Open</div></div><div class="kpi"><div class="num">${open.filter(f=>f.sev==='high').length}</div><div class="lbl">High Open</div></div><div class="kpi"><div class="num">${open.length}</div><div class="lbl">Total Open</div></div></div><div class="notice">Grouped by person, then code bucket. Clear individual rule, clear code, or clear person.</div><br>${list.map(renderFlagGroup).join('')||'<div class="card"><div class="card-title">No Exceptions</div>No exceptions found.</div>'}`}
function renderFlagGroup(g){const open=g.flags.filter(f=>!f.addressed),buckets=buildBuckets(g.flags);const critical=g.flags.filter(f=>f.sev==='critical'&&!f.addressed).length;return `<details class="flag-person-details"><summary><div class="flag-person"><strong>${esc(g.emp.name)}</strong><span>${esc(g.emp.shift)} · ${esc(g.emp.title)}</span></div><div>${open.length?`<span class="chip">${open.length} Open</span>`:''}${critical?'<span class="chip critical">Critical</span>':''}<span class="chip">${buckets.length} Code Bucket(s)</span></div><div>${open.length?`<button data-clear-person="${esc(g.emp.id)}">Clear Person</button>`:''}</div></summary><div class="flag-person-detail-body">${buckets.map(b=>renderBucket(g.emp,b)).join('')}</div></details>`}
function renderBucket(emp,b){const open=b.flags.filter(f=>!f.addressed);return `<details class="bucket"><summary><span class="badge ${esc(b.code)}">${esc(b.code)}</span><span>${esc(codeLabel(b.code))}<br><small>${esc(b.dateList.slice(0,8).map(fmt).join(', '))}${b.dateList.length>8?' ...':''}</small></span><span class="chip">${b.dateList.length} dates</span><span>${open.length?`<button class="sm" data-clear-code-emp="${esc(emp.id)}" data-clear-code="${esc(b.code)}">Clear ${esc(b.code)}</button>`:''}</span></summary><div class="bucket-body">${b.flags.map(renderExceptionCard).join('')}</div></details>`}function codeLabel(c){return CODES.find(x=>x[0]===c)?.[1]||'General'}function renderExceptionCard(f){return `<div class="exception-card ${f.sev} ${f.addressed?'addressed':''}"><div><div class="sev ${f.sev}">${f.sev}</div><span class="chip">${esc(f.type)}</span></div><div>${esc(f.msg)}<br><small>Issue Dates: ${esc(issueDateLabel(f.issueDates))}</small>${f.addressed?`<br><span class="ok">${esc(f.action.actionType||'Reviewed')} · ${esc(f.action.note||'')}</span>`:''}</div><div>${f.addressed?`<button class="sm" data-reopen="${esc(f.key)}">Reopen</button>`:`<button class="sm" data-action="Coaching" data-key="${esc(f.key)}">Coaching</button> <button class="sm" data-action="Verbal Warning" data-key="${esc(f.key)}">Verbal</button> <button class="sm" data-action="Written Warning" data-key="${esc(f.key)}">Written</button> <button class="sm" data-action="Final Warning" data-key="${esc(f.key)}">Final</button>`}</div></div>`}
function clearKeys(keys,actionType,note){const stamp=new Date().toISOString();for(const k of keys)attendance.flagActions[k]={at:stamp,actionType,note};audit('Flags cleared',`${keys.length} flag(s) · ${actionType}`);saveAttendance();safeRenderPages()}document.addEventListener('click',e=>{let b=e.target.closest('[data-action]');if(b){let note=prompt('Supervisor note:',b.dataset.action+' completed');if(note!==null)clearKeys([b.dataset.key],b.dataset.action,note||b.dataset.action);return}b=e.target.closest('[data-reopen]');if(b){delete attendance.flagActions[b.dataset.reopen];saveAttendance();safeRenderPages();return}b=e.target.closest('[data-clear-person]');if(b){let fs=computeFlags().filter(f=>f.emp.id===b.dataset.clearPerson&&!f.addressed);let note=prompt('Clear all open exceptions for this person:', 'Reviewed / cleared');if(note!==null)clearKeys(fs.map(f=>f.key),'Reviewed / Cleared',note);return}b=e.target.closest('[data-clear-code]');if(b){let fs=computeFlags().filter(f=>f.emp.id===b.dataset.clearCodeEmp&&!f.addressed&&(f.issueDates||[]).some(it=>it.code===b.dataset.clearCode));let note=prompt('Clear '+b.dataset.clearCode+' exceptions:', b.dataset.clearCode+' reviewed / cleared');if(note!==null)clearKeys([...new Set(fs.map(f=>f.key))],'Reviewed / Cleared',note);return}});
function renderAudit(){return `<div class="card"><div class="card-title">Attendance Audit Log</div><div class="table-wrap"><table><thead><tr><th>Date/Time</th><th>User</th><th>Action</th><th>Detail</th></tr></thead><tbody>${(attendance.audit||[]).slice(0,300).map(a=>`<tr><td>${esc(new Date(a.at).toLocaleString())}</td><td>${esc(a.user||'')}</td><td>${esc(a.action)}</td><td>${esc(a.detail)}</td></tr>`).join('')}</tbody></table></div></div>`}
async function importAttendanceJSON(input){const file=input&&input.files&&input.files[0];if(!file)return;try{const text=await file.text();const data=JSON.parse(text);if(!Array.isArray(data.employees)||!data.attendance||typeof data.attendance!=='object')throw new Error('File does not look like a PWADC attendance JSON export.');const oldCount=attendance.employees.length;attendance=data;normalizeAttendance();audit('Attendance JSON imported',file.name+' · '+attendance.employees.length+' employees · previous '+oldCount);await createAttendanceBackup();saveAttendance('import');entryDate='2026-06-01';gridEnd='2026-06-01';safeRenderPages();toast('Imported attendance JSON: '+file.name)}catch(e){toast('Import failed: '+e.message)}finally{if(input)input.value=''}}
document.addEventListener('keydown',function(ev){if(unlocked)return;if(ev.target&&['INPUT','TEXTAREA','SELECT'].includes(ev.target.tagName))return;const k=String(ev.key||'');if(/^\d$/.test(k)){ev.preventDefault();pinPress(k);return;}if(k==='Backspace'){ev.preventDefault();pinPress('X');return;}if(k==='Escape'||k.toLowerCase()==='c'){ev.preventDefault();pinPress('C');return;}if(k==='Enter'){ev.preventDefault();checkPin();return;}});
const KEY_CODE_MAP={p:'P',t:'T',a:'AL',l:'LE',w:'UE',e:'E',u:'U',v:'V',o:'O',f:'FL',n:'NE','1':'P','2':'T','3':'AL','4':'LE','5':'UE','6':'E','7':'U','8':'V','9':'O','0':'FL'};
document.addEventListener('keydown',function(ev){if(activeModule!=='attendance')return;if(ev.target&&['INPUT','TEXTAREA','SELECT'].includes(ev.target.tagName))return;const key=String(ev.key||'').toLowerCase();if(activeAttView==='grid'){if(ev.key==='ArrowUp'){ev.preventDefault();moveGridSelection(-1,0);return;}if(ev.key==='ArrowDown'){ev.preventDefault();moveGridSelection(1,0);return;}if(ev.key==='ArrowLeft'){ev.preventDefault();moveGridSelection(0,1);return;}if(ev.key==='ArrowRight'){ev.preventDefault();moveGridSelection(0,-1);return;}if(ev.key==='Delete'||ev.key==='Backspace'){ev.preventDefault();applyGridKeyboardCode('CLEAR');return;}const code=KEY_CODE_MAP[key];if(!code)return;ev.preventDefault();applyGridKeyboardCode(code);return;}if(activeAttView!=='daily')return;const code=KEY_CODE_MAP[key];if(!code)return;ev.preventDefault();activeCode=code;if(selectedEntryEmpId){setCode(selectedEntryEmpId,entryDate,code);const rows=currentRows();const i=rows.findIndex(e=>e.id===selectedEntryEmpId);if(i>=0&&i<rows.length-1)selectedEntryEmpId=rows[i+1].id;}safeRenderPages();});
async function reloadPackagedAttendanceData(){if(!confirm('Replace the current shared attendance data with the packaged latest JSON seed? A backup will be created first.'))return;try{await createAttendanceBackup();let r=await SuiteBridge.send('suite:resetModuleFromSeed',{}, {module:'attendance'});let raw=r.data;if(typeof raw==='string')attendance=JSON.parse(raw||'{}');else attendance=raw||{};normalizeAttendance();entryDate=attendance.lastSaved?attendance.lastSaved.slice(0,10):'2026-06-01';gridEnd=entryDate;safeRenderPages();toast('Loaded packaged latest attendance JSON');}catch(e){toast('Reload failed: '+e.message)}}
async function createAttendanceBackup(){try{let r=await SuiteBridge.send('suite:createBackup',attendance,{module:'attendance'});toast('Backup created');}catch(e){toast('Backup failed: '+e.message)}}function exportAttendanceCSV(){let rows=['Employee,Shift,Title,Date,Code,Note'];for(const e of attendance.employees){for(const [d,c] of Object.entries(attendance.attendance[e.id]||{})){let n=attendance.notes[e.id+'|'+d]||'';rows.push([e.name,e.shift,e.title,d,c,n].map(x=>'"'+String(x||'').replace(/"/g,'""')+'"').join(','))}}SuiteBridge.send('suite:writeExport',rows.join('\n'),{module:'attendance',fileName:'attendance-export-'+new Date().toISOString().slice(0,10)+'.csv'}).then(()=>toast('CSV exported')).catch(e=>toast('Export failed: '+e.message))}

function normalizeTasks(){tasks=tasks&&typeof tasks==='object'?tasks:{tasks:[],audit:[],nextId:1};tasks.tasks=Array.isArray(tasks.tasks)?tasks.tasks:[];tasks.audit=Array.isArray(tasks.audit)?tasks.audit:[];tasks.nextId=Number(tasks.nextId||0)||((tasks.tasks.reduce((m,t)=>Math.max(m,Number(t.id)||0),0))+1);for(const t of tasks.tasks){t.id=t.id||tasks.nextId++;t.project=t.project||'';t.status=t.status||'Active';t.priority=t.priority||'Medium';t.category=t.category||'General';t.owner=t.owner||'David';t.update=t.update||'';t.nextStep=t.nextStep||'';t.dueDate=t.dueDate||'';t.createdAt=t.createdAt||new Date().toISOString();t.updatedAt=t.updatedAt||new Date().toISOString();}}
async function loadTasks(){try{const res=await SuiteBridge.send('suite:loadModuleData',{}, {module:'tasks'});tasks=JSON.parse(res.data||'{}');normalizeTasks();}catch(e){tasks={tasks:[],audit:[],nextId:1};normalizeTasks();toast('Task data load failed: '+e.message)}}
async function saveTasksNow(reason='manual'){
  clearTimeout(taskSaveTimer);
  const save=document.getElementById('saveStatus');
  if(save)save.textContent='Saving tasks...';
  try{
    normalizeTasks();
    tasks.lastSaved=new Date().toISOString();
    await saveModuleDataStrict('tasks',tasks);
    if(save)save.textContent='Tasks saved '+new Date().toLocaleTimeString();
    return true;
  }catch(e){reportActionError('Task save',e);return false;}
}
function saveTasks(reason='autosave'){
  clearTimeout(taskSaveTimer);
  const save=document.getElementById('saveStatus');
  if(save)save.textContent='Saving tasks...';
  taskSaveTimer=setTimeout(()=>saveTasksNow(reason),350);
}
function taskAudit(action,detail){tasks.audit.unshift({at:new Date().toISOString(),user:env.user||'',machine:env.machine||'',action,detail});tasks.audit=tasks.audit.slice(0,500)}
function taskClass(st){let s=String(st||'').toLowerCase();if(s.includes('complete'))return'task-complete';if(s.includes('hold')||s.includes('table'))return'task-hold';if(s.includes('wait')||s.includes('follow'))return'task-waiting';if(s.includes('risk')||s.includes('blocked'))return'task-risk';if(s.includes('plan')||s.includes('final'))return'task-planning';return'task-active'}
function taskBadge(st){return `<span class="task-status ${taskClass(st)}">${esc(st||'Active')}</span>`}
function taskPriorityClass(p){p=String(p||'Medium').toLowerCase();return p.startsWith('h')?'priority-high':p.startsWith('l')?'priority-low':'priority-med'}
function taskDateShort(iso){if(!iso)return'';try{return new Date(iso+'T00:00:00').toLocaleDateString()}catch(e){return iso}}
function filteredTasks(){let q=taskSearch.toLowerCase().trim();return (tasks.tasks||[]).filter(t=>{if(taskStatusFilter!=='all'&&t.status!==taskStatusFilter)return false;if(taskPriorityFilter!=='all'&&t.priority!==taskPriorityFilter)return false;if(taskCategoryFilter!=='all'&&t.category!==taskCategoryFilter)return false;if(q&&!(`${t.project} ${t.status} ${t.priority} ${t.category} ${t.owner} ${t.update} ${t.nextStep}`.toLowerCase().includes(q)))return false;return true;}).sort((a,b)=>{const order={High:0,Medium:1,Low:2};return (order[a.priority]??1)-(order[b.priority]??1)||String(a.project).localeCompare(String(b.project));})}
function uniqueTaskValues(field){return [...new Set((tasks.tasks||[]).map(t=>t[field]).filter(Boolean))].sort()}
function taskMetrics(){let all=tasks.tasks||[];return{total:all.length,active:all.filter(t=>!['Complete','On Hold','Tabled'].includes(t.status)).length,waiting:all.filter(t=>['Waiting','Follow-up','Blocked'].includes(t.status)).length,high:all.filter(t=>t.priority==='High').length,done:all.filter(t=>t.status==='Complete').length}}
function renderTasks(){const m=taskMetrics();const list=filteredTasks();const statuses=uniqueTaskValues('status');const cats=uniqueTaskValues('category');return `<div class="page-head"><div><div class="page-title">Task Tracker</div><div class="page-sub">Weekly project command board · ${tasks.lastSaved?'Last saved '+new Date(tasks.lastSaved).toLocaleString():'Using packaged starter tasks'}</div></div><div class="top-actions"><button class="primary" onclick="openTaskModal()">+ Add Task</button><button class="gold" onclick="generateWeeklyUpdate()">Weekly Boss Update</button><button onclick="exportTasksCSV()">Export CSV</button><button onclick="createTaskBackup()">Backup Now</button><button onclick="document.getElementById('tasksImportFile').click()">Import JSON</button><button onclick="reloadPackagedTasksData()">Use Packaged Tasks</button><input id="tasksImportFile" type="file" accept=".json,application/json" class="hidden" onchange="importTasksJSON(this)"></div></div><div class="task-summary-row"><div class="kpi task-kpi-primary"><div class="num">${m.total}</div><div class="lbl">Total Projects</div></div><div class="kpi"><div class="num">${m.active}</div><div class="lbl">Active</div></div><div class="kpi"><div class="num">${m.waiting}</div><div class="lbl">Waiting / Follow-up</div></div><div class="kpi"><div class="num">${m.high}</div><div class="lbl">High Priority</div></div><div class="kpi"><div class="num">${m.done}</div><div class="lbl">Complete</div></div></div><div class="card"><div class="task-card-title"><div class="card-title">Task Controls</div><div class="mini-note">Tip: use status and priority to drive your weekly update.</div></div><div class="task-toolbar"><div><label>Search</label><input value="${esc(taskSearch)}" placeholder="Search project, update, next step..." oninput="taskSearch=this.value;safeRenderPages()"></div><div><label>Status</label><select onchange="taskStatusFilter=this.value;safeRenderPages()"><option value="all">All Statuses</option>${statuses.map(x=>`<option ${taskStatusFilter===x?'selected':''}>${esc(x)}</option>`).join('')}</select></div><div><label>Priority</label><select onchange="taskPriorityFilter=this.value;safeRenderPages()"><option value="all">All Priorities</option>${['High','Medium','Low'].map(x=>`<option ${taskPriorityFilter===x?'selected':''}>${x}</option>`).join('')}</select></div><div><label>Category</label><select onchange="taskCategoryFilter=this.value;safeRenderPages()"><option value="all">All Categories</option>${cats.map(x=>`<option ${taskCategoryFilter===x?'selected':''}>${esc(x)}</option>`).join('')}</select></div></div></div><div class="table-wrap"><table class="wide-table"><thead><tr><th>Project</th><th>Status</th><th>Priority</th><th>Category</th><th>Owner</th><th>Due</th><th>Current Update</th><th>Next Step</th><th>Actions</th></tr></thead><tbody>${list.map(t=>`<tr><td class="td-name">${esc(t.project)}</td><td>${taskBadge(t.status)}</td><td class="${taskPriorityClass(t.priority)}">${esc(t.priority)}</td><td>${esc(t.category||'')}</td><td>${esc(t.owner||'')}</td><td>${esc(taskDateShort(t.dueDate))}</td><td class="task-update">${esc(t.update||'')}</td><td class="task-update">${esc(t.nextStep||'')}</td><td><div class="task-actions"><button class="sm" onclick="openTaskModal(${Number(t.id)})">Edit</button><button class="sm" onclick="markTaskComplete(${Number(t.id)})">Done</button><button class="sm danger" onclick="removeTask(${Number(t.id)})">Remove</button></div></td></tr>`).join('')||'<tr><td colspan="9" class="empty">No tasks match current filters.</td></tr>'}</tbody></table></div>`}
function openTaskModal(id){taskEditId=id||null;const t=id?(tasks.tasks||[]).find(x=>Number(x.id)===Number(id)):{project:'',status:'Active',priority:'Medium',category:'General',owner:'David',dueDate:'',update:'',nextStep:''};if(!t){toast('Task not found');return;}showModal(`<div class="modal-title">${id?'Edit Task':'Add Task'}</div><div class="form-grid"><div class="form-group full"><label>Project / Task</label><input id="taskProject" value="${esc(t.project)}"></div><div class="form-group"><label>Status</label><select id="taskStatus">${['Active','Planning','Finalizing','Waiting','Follow-up','Blocked','On Hold','Tabled','Complete'].map(x=>`<option ${t.status===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="form-group"><label>Priority</label><select id="taskPriority">${['High','Medium','Low'].map(x=>`<option ${t.priority===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="form-group"><label>Category</label><input id="taskCategory" value="${esc(t.category||'General')}"></div><div class="form-group"><label>Owner</label><input id="taskOwner" value="${esc(t.owner||'David')}"></div><div class="form-group"><label>Target / Due Date</label><input type="date" id="taskDue" value="${esc(t.dueDate||'')}"></div><div class="form-group full"><label>Current Update</label><textarea id="taskUpdate" rows="4">${esc(t.update||'')}</textarea></div><div class="form-group full"><label>Next Step</label><textarea id="taskNext" rows="3">${esc(t.nextStep||'')}</textarea></div></div><div class="form-actions"><button onclick="closeModal()">Cancel</button><button class="primary" onclick="saveTaskFromModal()">Save Task</button></div>`)}
function saveTaskFromModal(){const data={project:document.getElementById('taskProject').value.trim(),status:document.getElementById('taskStatus').value,priority:document.getElementById('taskPriority').value,category:document.getElementById('taskCategory').value.trim()||'General',owner:document.getElementById('taskOwner').value.trim()||'David',dueDate:document.getElementById('taskDue').value,update:document.getElementById('taskUpdate').value.trim(),nextStep:document.getElementById('taskNext').value.trim()};if(!data.project){toast('Task needs a project name');return;}if(taskEditId){let t=tasks.tasks.find(x=>Number(x.id)===Number(taskEditId));Object.assign(t,data,{updatedAt:new Date().toISOString()});taskAudit('Updated task',data.project)}else{data.id=tasks.nextId++;data.createdAt=new Date().toISOString();data.updatedAt=new Date().toISOString();tasks.tasks.push(data);taskAudit('Added task',data.project)}saveTasksNow('task-modal').then(ok=>{if(ok){closeModal();safeRenderPages();toast('Task saved')}});}
function markTaskComplete(id){let t=tasks.tasks.find(x=>Number(x.id)===Number(id));if(!t)return;t.status='Complete';t.updatedAt=new Date().toISOString();taskAudit('Completed task',t.project);saveTasks();safeRenderPages()}
function removeTask(id){let t=tasks.tasks.find(x=>Number(x.id)===Number(id));if(!t)return;if(!confirm('Remove task: '+t.project+'?'))return;tasks.tasks=tasks.tasks.filter(x=>Number(x.id)!==Number(id));taskAudit('Removed task',t.project);saveTasks();safeRenderPages()}
async function createTaskBackup(){try{await SuiteBridge.send('suite:createBackup',tasks,{module:'tasks'});toast('Task backup created')}catch(e){toast('Task backup failed: '+e.message)}}
async function reloadPackagedTasksData(){if(!confirm('Replace current task tracker with the packaged starter task list? A backup will be created first.'))return;try{const res=await SuiteBridge.send('suite:resetModuleFromSeed',{}, {module:'tasks'});tasks=JSON.parse(res.data||'{}');normalizeTasks();toast('Packaged task tracker loaded');safeRenderPages();}catch(e){toast('Task seed restore failed: '+e.message)}}
async function importTasksJSON(input){const file=input&&input.files&&input.files[0];if(!file)return;try{const text=await file.text();const data=JSON.parse(text);if(!Array.isArray(data.tasks))throw new Error('File does not look like a PWADC task tracker JSON export.');tasks=data;normalizeTasks();taskAudit('Imported task JSON',file.name);saveTasks('import');safeRenderPages();toast('Task JSON imported')}catch(e){toast('Task import failed: '+e.message)}}
function exportTasksCSV(){let rows=[['Project','Status','Priority','Category','Owner','Due Date','Current Update','Next Step','Updated At'],...(tasks.tasks||[]).map(t=>[t.project,t.status,t.priority,t.category,t.owner,t.dueDate,t.update,t.nextStep,t.updatedAt])];downloadCSV('PWADC_Tasks_'+new Date().toISOString().slice(0,10)+'.csv',rows)}
function weeklyTaskText(){const today=new Date().toLocaleDateString();let list=(tasks.tasks||[]).filter(t=>t.status!=='Complete').sort((a,b)=>String(a.category||'').localeCompare(String(b.category||''))||String(a.project).localeCompare(String(b.project)));let lines=['Security Projects Weekly Update - '+today,''];for(const t of list){lines.push(t.project+' - '+(t.update||'No current update entered.')+(t.nextStep?' Next step: '+t.nextStep:''));}return lines.join('\n')}
function weeklyTaskHtml(){const today=new Date().toLocaleDateString();let list=(tasks.tasks||[]).filter(t=>t.status!=='Complete').sort((a,b)=>String(a.category||'').localeCompare(String(b.category||''))||String(a.project).localeCompare(String(b.project)));return `<!doctype html><html><head><meta charset="utf-8"><title>PWADC Security Weekly Project Update</title><style>body{font-family:Segoe UI,Arial,sans-serif;margin:28px;color:#1d2430}h1{color:#8f1c21;margin-bottom:4px}.sub{color:#667085;margin-bottom:22px}.item{border-left:4px solid #C0272D;background:#f5f6f8;margin:10px 0;padding:10px 14px;border-radius:6px}.project{font-weight:800;color:#1e2330}.meta{font-size:12px;color:#667085;margin:2px 0 8px}.next{margin-top:6px;color:#344054}button{padding:8px 14px;margin-bottom:18px}

.audit-native-frame-wrap{border:1px solid var(--border);border-radius:10px;overflow:hidden;background:var(--surface);height:calc(100vh - 150px);min-height:720px}.audit-native-frame{width:100%;height:100%;border:0;background:#fff}.audit-action-note{margin-bottom:12px}
</style></head><body><button onclick="window.print()">Print</button><h1>PWADC Security Weekly Project Update</h1><div class="sub">Generated ${esc(today)} · ${list.length} active projects</div>${list.map(t=>`<div class="item"><div class="project">${esc(t.project)}</div><div class="meta">${esc(t.status)} · ${esc(t.priority)} Priority · ${esc(t.category||'General')}</div><div>${esc(t.update||'No current update entered.')}</div>${t.nextStep?`<div class="next"><strong>Next step:</strong> ${esc(t.nextStep)}</div>`:''}</div>`).join('')}</body></html>`}
function taskEmailBody(){return weeklyTaskText()+"\n\nRespectfully,\nDavid"}
function openWeeklyTaskEmail(){const subject='PWADC Security Weekly Project Update - '+new Date().toLocaleDateString();const body=taskEmailBody();const mailto='mailto:jfaure@pwadc.com?subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent(body);const a=document.createElement('a');a.href=mailto;a.style.display='none';document.body.appendChild(a);a.click();setTimeout(()=>{try{a.remove()}catch(e){}},1000);toast('Opening email draft to jfaure@pwadc.com')}
async function generateWeeklyUpdate(){const html=weeklyTaskHtml();const txt=weeklyTaskText();const date=new Date().toISOString().slice(0,10);try{await SuiteBridge.send('suite:writeExport',html,{module:'tasks',fileName:'PWADC_Weekly_Project_Update_'+date+'.html'});await SuiteBridge.send('suite:writeExport',txt,{module:'tasks',fileName:'PWADC_Weekly_Project_Update_'+date+'.txt'});toast('Weekly update exported and email draft opening');}catch(e){toast('Weekly export failed: '+e.message)}openWeeklyTaskEmail();showModal(`<div class="modal-title">Weekly Boss Update</div><div class="notice">A preformatted email draft should open to <strong>jfaure@pwadc.com</strong>. HTML and plain text copies were also exported to the Task Tracker export folder.</div><div class="weekly-preview">${esc(txt)}</div><div class="form-actions"><button onclick="closeModal()">Close</button><button onclick="openWeeklyTaskEmail()">Open Email Again</button><button class="primary" onclick="printWeeklyTaskUpdate()">Print Preview</button></div>`)}
function printWeeklyTaskUpdate(){let w=window.open('','_blank');if(!w){toast('Popup blocked. Allow popups to preview weekly update.');return;}w.document.write(weeklyTaskHtml());w.document.close();}

function openSettings(){renderSettings();document.getElementById('settingsPanel').classList.add('open')}function closeSettings(){document.getElementById('settingsPanel').classList.remove('open')}function renderSettings(){document.getElementById('settingsBody').innerHTML=`<div class="form-grid"><div><label>Theme</label><select id="setTheme"><option ${settings.theme==='dark'?'selected':''}>dark</option><option ${settings.theme==='light'?'selected':''}>light</option><option ${settings.theme==='auto'?'selected':''}>auto</option></select></div><div><label>Default Module</label><select id="setDefault">${MODULES.map(m=>`<option value="${m.id}" ${settings.defaultModule===m.id?'selected':''}>${m.label}</option>`).join('')}</select></div><div><label>PIN</label><input id="setPin" value="${esc(settings.pin)}" maxlength="8"></div><div><label>Backup Retention Days</label><input id="setRetention" type="number" value="${settings.backupRetentionDays}"></div><div class="full"><label>Data Root</label><input id="setRoot" value="${esc(settings.dataRoot)}"></div><div class="full"><button class="primary" onclick="saveSettings()">Save Settings</button> <button onclick="runHealthCheck()">Run Health Check</button> <button class="gold" onclick="backupEverything()">Backup Everything</button></div></div><div id="healthBox" style="margin-top:14px"></div>`}async function saveSettings(){settings={...settings,theme:document.getElementById('setTheme').value,defaultModule:document.getElementById('setDefault').value,pin:document.getElementById('setPin').value||'1234',dataRoot:document.getElementById('setRoot').value,backupRetentionDays:Number(document.getElementById('setRetention').value||60)};applyTheme();try{await SuiteBridge.send('suite:saveSettings',settings);toast('Settings saved')}catch(e){toast('Settings failed: '+e.message)}}async function backupEverything(){
  const stamp=new Date().toLocaleString();
  const results=[];
  try{await SuiteBridge.send('suite:createBackup',attendance,{module:'attendance'});results.push({name:'Attendance',ok:true});}catch(e){results.push({name:'Attendance',ok:false,error:e.message});}
  try{await SuiteBridge.send('suite:createBackup',roster,{module:'roster'});results.push({name:'Roster',ok:true});}catch(e){results.push({name:'Roster',ok:false,error:e.message});}
  try{await SuiteBridge.send('suite:createBackup',tasks,{module:'tasks'});results.push({name:'Task Tracker',ok:true});}catch(e){results.push({name:'Task Tracker',ok:false,error:e.message});}
  try{await SuiteBridge.send('suite:createBackup',settings,{module:'suite-settings'});results.push({name:'Suite Settings',ok:true});}catch(e){results.push({name:'Suite Settings',ok:false,error:e.message});}
  try{await SuiteBridge.send('suite:backupPrograms');results.push({name:'Standalone Programs',ok:true});}catch(e){results.push({name:'Standalone Programs',ok:false,error:e.message});}
  const okCount=results.filter(r=>r.ok).length;
  const box=document.getElementById('healthBox');
  if(box)box.innerHTML=`<div class="card"><div class="card-title">Backup Everything</div><div style="color:var(--muted);font-size:12px;margin-bottom:8px">Run ${esc(stamp)}</div>${results.map(r=>`<div class="health-row"><span>${esc(r.name)}</span><span class="${r.ok?'ok':'bad'}">${r.ok?'BACKED UP':esc(r.error||'FAILED')}</span></div>`).join('')}</div>`;
  toast(okCount===results.length?'Everything backed up':'Backup completed with '+(results.length-okCount)+' issue(s)');
}
async function runHealthCheck(){try{let r=await SuiteBridge.send('suite:healthCheck');document.getElementById('healthBox').innerHTML=`<div class="card"><div class="card-title">Health Check</div><div style="color:var(--muted);font-size:12px;margin-bottom:8px">${esc(r.dataRoot)}</div>${r.checks.map(c=>`<div class="health-row"><span>${esc(c.name)}</span><span class="${c.ok?'ok':'bad'}">${c.ok?'OK':esc(c.error)}</span></div>`).join('')}</div>`}catch(e){toast('Health check failed')}}


function applyViewportSizing(){
  const root=document.documentElement;
  const w=window.innerWidth||document.documentElement.clientWidth||1400;
  const h=window.innerHeight||document.documentElement.clientHeight||900;
  let view='standard';
  if(w<1280 || h<760) view='compact';
  else if(w>=2200) view='wide';
  root.setAttribute('data-view',view);
  root.style.setProperty('--vh',(h*0.01)+'px');
}
let viewportResizeTimer=null;
window.addEventListener('resize',()=>{clearTimeout(viewportResizeTimer);viewportResizeTimer=setTimeout(()=>{applyViewportSizing();try{safeRenderPages();}catch(_){ }},120);});
window.addEventListener('orientationchange',()=>setTimeout(applyViewportSizing,150));
applyViewportSizing();

init();
